// ============ Dashboard (computador) — gráficos em SVG puro, sem biblioteca ============
function saudacaoDoDia() {
  const h = new Date().getHours();
  return h < 12 ? "Bom dia" : h < 18 ? "Boa tarde" : "Boa noite";
}
function chaveDia(d) {
  const x = new Date(d);
  return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, "0")}-${String(x.getDate()).padStart(2, "0")}`;
}
function abreviarNumero(v) {
  const n = Number(v) || 0;
  if (n >= 1000000) return `${(n / 1000000).toFixed(1).replace(".", ",")}M`;
  if (n >= 1000) return `${(n / 1000).toFixed(1).replace(".", ",")}k`;
  return String(Math.round(n));
}

function DashCard({ T, title, subtitle, right, children, className = "" }) {
  return (
    <section style={{ background: T.card, borderColor: T.border }} className={`rounded-2xl border shadow-sm flex flex-col min-w-0 ${className}`}>
      {(title || right) && (
        <header className="flex items-start justify-between gap-3 px-5 pt-4">
          <div className="min-w-0">
            <h3 style={{ color: T.text }} className="text-sm font-bold">{title}</h3>
            {subtitle && <p style={{ color: T.subtext }} className="text-[11px] mt-0.5">{subtitle}</p>}
          </div>
          {right}
        </header>
      )}
      <div className="px-5 pb-5 pt-3 flex-1">{children}</div>
    </section>
  );
}

function DashSpark({ data, color, gid, height = 46 }) {
  const w = 160, h = height;
  const d = data && data.length > 1 ? data : [0, 0];
  const max = Math.max(...d, 0), min = Math.min(...d, 0), span = max - min || 1;
  const step = w / (d.length - 1);
  const pts = d.map((v, i) => [i * step, h - 4 - ((v - min) / span) * (h - 10)]);
  const linha = pts.map((p, i) => `${i ? "L" : "M"}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(" ");
  return (
    <svg viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" className="w-full block" style={{ height }}>
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.3" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={`${linha} L${w},${h} L0,${h} Z`} fill={`url(#${gid})`} />
      <path d={linha} fill="none" stroke={color} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
    </svg>
  );
}

function DashKpi({ T, label, value, sub, chip, chipBom, Icon, accent, children }) {
  const chipStyle = chipBom ? { background: "#E6F7ED", color: "#1F9D55" } : { background: RED_SOFT, color: RED_DARK };
  return (
    <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl border shadow-sm p-5 flex flex-col min-w-0">
      <div className="flex items-center justify-between gap-2">
        <p style={{ color: T.subtext }} className="text-[11px] font-bold uppercase tracking-wide truncate">{label}</p>
        <div style={{ background: `${accent}1F` }} className="h-8 w-8 rounded-xl flex items-center justify-center shrink-0"><Icon size={16} color={accent} /></div>
      </div>
      {/* valor nunca sai da caixa: fonte se ajusta ao tamanho do texto e ao espaço disponível */}
      <div className="flex items-end gap-2 mt-2 min-w-0 flex-wrap">
        <p style={{ color: T.text, fontSize: String(value ?? "").length > 12 ? "clamp(17px, 1.55vw, 24px)" : String(value ?? "").length > 8 ? "clamp(19px, 1.8vw, 26px)" : "28px" }}
          className="font-extrabold leading-none tabular-nums whitespace-nowrap overflow-hidden text-ellipsis max-w-full" title={String(value ?? "")}>{value}</p>
        {chip && <span style={chipStyle} className="text-[11px] font-bold px-1.5 py-0.5 rounded-md mb-0.5">{chip}</span>}
      </div>
      {sub && <p style={{ color: T.subtext }} className="text-[11px] mt-1.5">{sub}</p>}
      <div className="mt-3">{children}</div>
    </div>
  );
}

function DashBars({ T, data, W = 760 }) {
  const H = 250, pb = 26, pt = 16;
  const totais = data.map((d) => d.parts.reduce((a, p) => a + p.value, 0));
  const topo = Math.max(4, Math.ceil(Math.max(...totais, 0) / 4) * 4);
  const pl = 16 + String(topo).length * 6.5;
  const ih = H - pb - pt, bw = (W - pl) / data.length;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="w-full block">
      {[0, 1, 2, 3, 4].map((g) => {
        const y = pt + ih - (ih * g) / 4;
        return (
          <g key={g}>
            <line x1={pl} x2={W} y1={y} y2={y} stroke={T.border} strokeDasharray={g === 0 ? undefined : "3 4"} />
            <text x={pl - 8} y={y + 3.5} textAnchor="end" fontSize="10" fill={T.subtext}>{Math.round((topo * g) / 4)}</text>
          </g>
        );
      })}
      {data.map((d, i) => {
        let acc = 0;
        const x = pl + i * bw + bw * 0.18, w = bw * 0.64;
        return (
          <g key={i}>
            {d.parts.filter((p) => p.value > 0).map((p, k) => {
              const h = (p.value / topo) * ih; acc += h;
              return <rect key={k} x={x} y={pt + ih - acc} width={w} height={h} fill={p.color} rx="2" />;
            })}
            {totais[i] > 0 && <text x={x + w / 2} y={pt + ih - acc - 5} textAnchor="middle" fontSize="10" fontWeight="700" fill={T.text}>{totais[i]}</text>}
            <text x={x + w / 2} y={H - 8} textAnchor="middle" fontSize="10" fill={T.subtext}>{d.label}</text>
          </g>
        );
      })}
    </svg>
  );
}

function DashArea({ T, data, color, gid }) {
  const W = 760, H = 230, pl = 44, pb = 26, pt = 14;
  const max = Math.max(...data.map((d) => d.value), 0);
  const topo = max > 0 ? max * 1.15 : 1;
  const iw = W - pl - 8, ih = H - pb - pt, step = iw / Math.max(data.length - 1, 1);
  const pts = data.map((d, i) => [pl + i * step, pt + ih - (d.value / topo) * ih]);
  const linha = pts.map((p, i) => `${i ? "L" : "M"}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(" ");
  const marcas = (data.length <= 8 ? data.map((_, i) => i) : [0, 7, 14, 21, data.length - 1]).filter((v, i, a) => v >= 0 && v < data.length && a.indexOf(v) === i);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="w-full block">
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.28" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>
      {[0, 1, 2, 3].map((g) => {
        const y = pt + ih - (ih * g) / 3;
        return (
          <g key={g}>
            <line x1={pl} x2={W - 8} y1={y} y2={y} stroke={T.border} strokeDasharray={g === 0 ? undefined : "3 4"} />
            <text x={pl - 8} y={y + 3.5} textAnchor="end" fontSize="10" fill={T.subtext}>{abreviarNumero((topo * g) / 3)}</text>
          </g>
        );
      })}
      <path d={`${linha} L${pl + iw},${pt + ih} L${pl},${pt + ih} Z`} fill={`url(#${gid})`} />
      <path d={linha} fill="none" stroke={color} strokeWidth="2.2" strokeLinejoin="round" strokeLinecap="round" />
      {data.map((d, i) => d.value > 0 && <circle key={i} cx={pts[i][0]} cy={pts[i][1]} r="2.8" fill={T.card} stroke={color} strokeWidth="1.8" />)}
      {marcas.map((i) => <text key={i} x={pts[i][0]} y={H - 8} textAnchor={i === data.length - 1 ? "end" : "middle"} fontSize="10" fill={T.subtext}>{data[i].label}</text>)}
    </svg>
  );
}

function DashDonut({ T, segments, centerValue, centerLabel, size = 176, thickness = 22 }) {
  const total = segments.reduce((a, s) => a + s.value, 0);
  const r = (size - thickness) / 2, c = size / 2, circ = 2 * Math.PI * r;
  let acc = 0;
  return (
    <div className="relative shrink-0" style={{ width: size, height: size }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        <circle cx={c} cy={c} r={r} fill="none" stroke={T.chipBg} strokeWidth={thickness} />
        {total > 0 && segments.filter((s) => s.value > 0).map((s) => {
          const len = (s.value / total) * circ;
          const el = <circle key={s.label} cx={c} cy={c} r={r} fill="none" stroke={s.color} strokeWidth={thickness}
            strokeDasharray={`${Math.max(len - 2, 0)} ${circ - Math.max(len - 2, 0)}`} strokeDashoffset={-acc} transform={`rotate(-90 ${c} ${c})`} />;
          acc += len;
          return el;
        })}
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <p style={{ color: T.text }} className="text-2xl font-extrabold leading-none tabular-nums">{centerValue}</p>
        <p style={{ color: T.subtext }} className="text-[10px] mt-1 font-semibold uppercase tracking-wide">{centerLabel}</p>
      </div>
    </div>
  );
}

function DashboardView({ T, items, historico, rondas, auditoria, nome, lojaNumero, onOpenDetail, onTab, onFlow }) {
  const fmt = useFormatarMoedaComCamada();
  const d = useMemo(() => {
    const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
    const ddmm = (dt) => `${String(dt.getDate()).padStart(2, "0")}/${String(dt.getMonth() + 1).padStart(2, "0")}`;
    const lista = (items || []).filter((i) => i && i.validade).map((i) => ({
      ...i, status: getStatus(i), valor: (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0),
    })).filter((i) => Number.isFinite(i.status.d));
    const nivel = (lv) => lista.filter((i) => i.status.level === lv);
    const soma = (arr) => arr.reduce((a, i) => a + i.valor, 0);
    const venc = nivel("expired"), alerta = nivel("alert"), atencao = nivel("warning"), ok = nivel("ok");

    // Vencimentos: coluna 0 = já vencidos, 1 = hoje, 2.. = próximos dias
    const dias = Array.from({ length: 15 }, (_, k) => {
      const dt = new Date(hoje); dt.setDate(dt.getDate() + (k - 1));
      return { label: k === 0 ? "Venc." : k === 1 ? "Hoje" : ddmm(dt), expired: 0, alert: 0, warning: 0, ok: 0, valor: 0 };
    });
    lista.forEach((i) => {
      const idx = i.status.d < 0 ? 0 : i.status.d + 1;
      if (idx > 14) return;
      dias[idx][i.status.level] += 1;
      dias[idx].valor += i.valor;
    });

    // Perdas (baixas de produto que já estava vencido) nos últimos 30 dias x 30 dias anteriores
    const serie = Array.from({ length: 30 }, (_, k) => {
      const dt = new Date(hoje); dt.setDate(dt.getDate() - (29 - k));
      return { dt, label: ddmm(dt), value: 0 };
    });
    const indice = {};
    serie.forEach((s, k) => { indice[chaveDia(s.dt)] = k; });
    const ini30 = serie[0].dt.getTime(), ini60 = ini30 - 30 * 86400000;
    let perda30 = 0, perdaPrev = 0, baixas30 = 0;
    const motivos = {};
    (historico || []).forEach((h) => {
      if (!h.dataBaixa) return;
      const t = new Date(h.dataBaixa).getTime();
      if (!Number.isFinite(t)) return;
      if (t >= ini30) { baixas30 += 1; const m = h.motivo || "Sem motivo"; motivos[m] = (motivos[m] || 0) + 1; }
      if (!h.vencidoAntes) return;
      const v = (Number(h.quantidade) || 1) * (Number(h.precoUnitario) || 0);
      const key = chaveDia(h.dataBaixa);
      if (key in indice) { serie[indice[key]].value += v; perda30 += v; }
      else if (t >= ini60 && t < ini30) perdaPrev += v;
    });
    const motivosLista = Object.entries(motivos).sort((a, b) => b[1] - a[1]).slice(0, 6);

    const porSetor = {};
    lista.forEach((i) => {
      const s = i.setor || "Sem setor";
      if (!porSetor[s]) porSetor[s] = { setor: s, total: 0, risco: 0, valor: 0 };
      porSetor[s].total += 1;
      if (i.status.level === "alert" || i.status.level === "expired") { porSetor[s].risco += 1; porSetor[s].valor += i.valor; }
    });
    const setores = Object.values(porSetor).sort((a, b) => b.risco - a.risco || b.total - a.total);

    const agoraISO = new Date().toISOString();
    const rondasSetor = setores.map((s) => {
      const doSetor = (rondas || []).filter((r) => r.setor === s.setor);
      const deHoje = doSetor.filter((r) => isSameDay(r.finalizadoEm || r.iniciadoEm, agoraISO));
      const concluida = deHoje.find((r) => r.status === "concluida");
      const parcial = deHoje.find((r) => r.status === "parcial" || r.status === "em_andamento");
      const ultima = doSetor.map((r) => r.finalizadoEm).filter(Boolean).sort().pop() || null;
      return { ...s, estado: concluida ? "ok" : parcial ? "parcial" : "pendente", ultima };
    });

    const troca = { com: 0, sem: 0, nao: 0, valorSem: 0 };
    lista.forEach((i) => {
      if (i.politicaTroca === "sem_troca") { troca.sem += 1; troca.valorSem += i.valor; }
      else if (i.politicaTroca === "com_troca") troca.com += 1;
      else troca.nao += 1;
    });

    return {
      lista, venc, alerta, atencao, ok, dias, serie, perda30, perdaPrev, baixas30, motivosLista, setores, rondasSetor, troca,
      valorVenc: soma(venc), valorAlerta: soma(alerta),
      criticos: lista.filter((i) => i.status.level !== "ok").sort((a, b) => a.status.d - b.status.d).slice(0, 8),
      feed: [...(auditoria || [])].sort((a, b) => new Date(b.criadoEm) - new Date(a.criadoEm)).slice(0, 8),
    };
  }, [items, historico, rondas, auditoria]);

  const nomeCurto = (nome || "").trim().split(/\s+/)[0] || "";
  const dataBruta = new Date().toLocaleDateString("pt-BR", { weekday: "long", day: "2-digit", month: "long" });
  const dataHoje = dataBruta.charAt(0).toUpperCase() + dataBruta.slice(1);
  const valorRisco = d.valorVenc + d.valorAlerta;
  const emRisco = d.venc.length + d.alerta.length;
  const deltaPerda = d.perdaPrev > 0 ? ((d.perda30 - d.perdaPrev) / d.perdaPrev) * 100 : null;
  const total = d.lista.length;
  const pct = (n) => (total ? Math.round((n / total) * 100) : 0);
  const COR = { expired: RED_DARK, alert: RED, warning: "#C98A0C", ok: "#1F9D55" };
  const maxSetor = Math.max(...d.setores.map((s) => s.total), 1);
  const maxMotivo = Math.max(...d.motivosLista.map((m) => m[1]), 1);
  const rondasOk = d.rondasSetor.filter((s) => s.estado === "ok").length;

  return (
    <div className="flex flex-col gap-5 pt-6">
      {/* Banner de boas-vindas */}
      <div style={{ background: `linear-gradient(120deg, ${BLUE_DARK} 0%, ${BLUE} 65%, #2F6FC0 100%)` }} className="relative overflow-hidden rounded-2xl px-8 py-7 text-white">
        <svg className="absolute right-0 top-0 h-full w-[46%] pointer-events-none" viewBox="0 0 400 200" preserveAspectRatio="xMaxYMid slice" aria-hidden="true">
          <polygon points="400,0 400,200 190,200" fill="#fff" opacity="0.07" />
          <polygon points="400,0 400,120 260,0" fill="#fff" opacity="0.1" />
          <polygon points="330,200 400,90 400,200" fill={RED} opacity="0.85" />
          <circle cx="250" cy="48" r="26" fill="#fff" opacity="0.08" />
        </svg>
        <div className="relative max-w-2xl">
          <p className="text-white/70 text-xs font-semibold">{dataHoje}{lojaNumero ? ` · Loja ${lojaNumero}` : ""}</p>
          <h2 className="text-[26px] font-extrabold leading-tight mt-1">{saudacaoDoDia()}{nomeCurto ? `, ${nomeCurto}` : ""}! 👋</h2>
          <p className="text-white/85 text-sm mt-2 leading-relaxed">
            {total === 0
              ? "Ainda não há produtos monitorados nesta loja."
              : <>Hoje a loja tem <strong>{d.venc.length}</strong> produto(s) vencido(s) e <strong>{d.alerta.length}</strong> em alerta, somando <strong>{fmt(valorRisco)}</strong> em risco.</>}
          </p>
          <div className="flex gap-2.5 mt-5">
            <button onClick={() => onFlow("prioridade")} style={{ background: "#fff", color: BLUE_DARK }} className="px-4 py-2 rounded-xl text-xs font-bold hover:opacity-90 transition">Ver prioridades de perda</button>
            <button onClick={() => onTab("produtos")} style={{ background: "rgba(255,255,255,0.16)", color: "#fff" }} className="px-4 py-2 rounded-xl text-xs font-bold hover:bg-white/25 transition">Produtos monitorados</button>
          </div>
        </div>
      </div>

      {/* Indicadores */}
      <div className="grid grid-cols-2 xl:grid-cols-4 gap-5">
        <DashKpi T={T} label="Valor em risco" value={fmt(valorRisco)} sub={`${emRisco} produto(s) vencidos ou em alerta`} Icon={DollarSign} accent={RED}>
          <DashSpark data={d.dias.map((x) => x.valor)} color={RED} gid="sp-risco" />
        </DashKpi>
        <DashKpi T={T} label="Vencidos" value={d.venc.length} sub={`${fmt(d.valorVenc)} em produtos vencidos`} chip={`${pct(d.venc.length)}%`} Icon={AlertTriangle} accent={RED_DARK}>
          <div style={{ background: T.chipBg }} className="h-1.5 rounded-full overflow-hidden"><div style={{ width: `${pct(d.venc.length)}%`, background: RED_DARK }} className="h-full rounded-full" /></div>
        </DashKpi>
        <DashKpi T={T} label="Em alerta" value={d.alerta.length} sub={`${d.atencao.length} em atenção · ${d.ok.length} no prazo`} chip={`${pct(d.alerta.length)}%`} Icon={Clock} accent="#C98A0C">
          <div style={{ background: T.chipBg }} className="h-1.5 rounded-full overflow-hidden"><div style={{ width: `${pct(d.alerta.length)}%`, background: "#C98A0C" }} className="h-full rounded-full" /></div>
        </DashKpi>
        <DashKpi T={T} label="Perdas em 30 dias" value={fmt(d.perda30)} sub={`${d.baixas30} baixa(s) registrada(s)`}
          chip={deltaPerda === null ? null : `${deltaPerda > 0 ? "+" : ""}${Math.round(deltaPerda)}%`} chipBom={deltaPerda !== null && deltaPerda <= 0} Icon={TrendingDown} accent={BLUE}>
          <DashSpark data={d.serie.map((x) => x.value)} color={BLUE} gid="sp-perda" />
        </DashKpi>
      </div>

      {/* Vencimentos + status */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-5">
        <DashCard T={T} className="xl:col-span-2" title="Vencimentos nos próximos 14 dias" subtitle="Quantidade de produtos por data de vencimento"
          right={
            <div className="flex flex-wrap justify-end gap-x-3 gap-y-1">
              {[["Vencido", COR.expired], ["Em alerta", COR.alert], ["Atenção", COR.warning], ["No prazo", COR.ok]].map(([l, c]) => (
                <span key={l} style={{ color: T.subtext }} className="flex items-center gap-1.5 text-[10px] font-semibold"><i style={{ background: c }} className="h-2 w-2 rounded-full inline-block" />{l}</span>
              ))}
            </div>
          }>
          <DashBars T={T} data={d.dias.map((x) => ({ label: x.label, parts: [
            { value: x.expired, color: COR.expired }, { value: x.alert, color: COR.alert }, { value: x.warning, color: COR.warning }, { value: x.ok, color: COR.ok },
          ] }))} />
        </DashCard>
        <DashCard T={T} title="Situação dos produtos" subtitle={`${total} produto(s) monitorados`}>
          <div className="flex flex-col items-center gap-5 pt-1">
            <DashDonut T={T} centerValue={total} centerLabel="produtos" segments={[
              { label: "Vencidos", value: d.venc.length, color: COR.expired }, { label: "Em alerta", value: d.alerta.length, color: COR.alert },
              { label: "Atenção", value: d.atencao.length, color: COR.warning }, { label: "No prazo", value: d.ok.length, color: COR.ok },
            ]} />
            <div className="w-full grid grid-cols-2 gap-x-4 gap-y-2">
              {[["Vencidos", d.venc.length, COR.expired], ["Em alerta", d.alerta.length, COR.alert], ["Atenção", d.atencao.length, COR.warning], ["No prazo", d.ok.length, COR.ok]].map(([l, n, c]) => (
                <div key={l} className="flex items-center gap-2 text-xs">
                  <i style={{ background: c }} className="h-2.5 w-2.5 rounded-full inline-block shrink-0" />
                  <span style={{ color: T.subtext }} className="flex-1">{l}</span>
                  <strong style={{ color: T.text }} className="tabular-nums">{n}</strong>
                </div>
              ))}
            </div>
          </div>
        </DashCard>
      </div>

      {/* Perdas + motivos */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-5">
        <DashCard T={T} className="xl:col-span-2" title="Perdas por dia" subtitle="Valor em R$ de produtos baixados já vencidos — últimos 30 dias"
          right={<span style={{ color: T.text }} className="text-sm font-extrabold tabular-nums">{fmt(d.perda30)}</span>}>
          <DashArea T={T} data={d.serie} color={RED} gid="ar-perda" />
        </DashCard>
        <DashCard T={T} title="Ações registradas" subtitle="Baixas por motivo — últimos 30 dias">
          {d.motivosLista.length === 0 ? (
            <p style={{ color: T.subtext }} className="text-xs py-8 text-center">Nenhuma baixa registrada no período.</p>
          ) : (
            <div className="flex flex-col gap-3.5 pt-1">
              {d.motivosLista.map(([m, n]) => (
                <div key={m}>
                  <div className="flex items-center justify-between text-xs mb-1.5"><span style={{ color: T.text }} className="font-medium truncate pr-2">{m}</span><strong style={{ color: T.text }} className="tabular-nums">{n}</strong></div>
                  <div style={{ background: T.chipBg }} className="h-2 rounded-full overflow-hidden"><div style={{ width: `${(n / maxMotivo) * 100}%`, background: BLUE }} className="h-full rounded-full" /></div>
                </div>
              ))}
            </div>
          )}
        </DashCard>
      </div>

      {/* Tabela de críticos + rondas */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-5">
        <DashCard T={T} className="xl:col-span-2" title="Produtos mais críticos" subtitle="Os que vencem primeiro e pedem ação"
          right={<button onClick={() => onFlow("prioridade")} style={{ color: BLUE }} className="text-[11px] font-bold hover:underline shrink-0">Ver prioridades →</button>}>
          {d.criticos.length === 0 ? (
            <p style={{ color: T.subtext }} className="text-xs py-8 text-center">Nenhum produto vencido ou em alerta. 🎉</p>
          ) : (
            <div className="overflow-x-auto -mx-1">
              <table className="w-full text-left text-xs min-w-[520px]">
                <thead>
                  <tr style={{ color: T.subtext, borderColor: T.border }} className="border-b text-[10px] uppercase tracking-wide">
                    <th className="font-bold py-2 px-1">Produto</th><th className="font-bold py-2 px-1">Setor</th><th className="font-bold py-2 px-1">Validade</th>
                    <th className="font-bold py-2 px-1 text-right">Qtd</th><th className="font-bold py-2 px-1 text-right">Valor</th><th className="font-bold py-2 px-1 text-right">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {d.criticos.map((i) => {
                    const st = statusStyles(i.status.level);
                    return (
                      <tr key={i.id} onClick={() => onOpenDetail(i)} style={{ borderColor: T.border }} className="border-b last:border-0 cursor-pointer hover:opacity-75">
                        <td className="py-2.5 px-1">
                          <div className="flex items-center gap-2.5 min-w-0">
                            <Thumb foto={i.foto} size={32} rounded="rounded-lg" />
                            <span style={{ color: T.text }} className="font-semibold truncate max-w-[220px]">{i.nome}</span>
                          </div>
                        </td>
                        <td style={{ color: T.subtext }} className="py-2.5 px-1">{i.setor}</td>
                        <td style={{ color: T.text }} className="py-2.5 px-1 tabular-nums">{formatarData(i.validade)}</td>
                        <td style={{ color: T.text }} className="py-2.5 px-1 text-right tabular-nums">{i.quantidade || 1}</td>
                        <td style={{ color: T.text }} className="py-2.5 px-1 text-right tabular-nums font-semibold">{fmt(i.valor)}</td>
                        <td className="py-2.5 px-1 text-right">
                          <span style={{ background: st.bg, color: st.fg }} className="text-[10px] font-bold px-2 py-1 rounded-md whitespace-nowrap">
                            {i.status.d < 0 ? `${-i.status.d}d vencido` : i.status.d === 0 ? "Vence hoje" : `${i.status.d}d`}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </DashCard>
        <DashCard T={T} title="Rondas de hoje" subtitle={d.rondasSetor.length ? `${rondasOk} de ${d.rondasSetor.length} setores conferidos` : "Sem setores ainda"}
          right={<button onClick={() => onTab("rondas")} style={{ color: BLUE }} className="text-[11px] font-bold hover:underline shrink-0">Abrir →</button>}>
          <div className="flex flex-col gap-1 -mx-1">
            {d.rondasSetor.slice(0, 8).map((s) => {
              const cor = s.estado === "ok" ? "#1F9D55" : s.estado === "parcial" ? "#C98A0C" : T.subtext;
              return (
                <div key={s.setor} className="flex items-center gap-3 px-1 py-2">
                  <i style={{ background: cor }} className="h-2.5 w-2.5 rounded-full shrink-0" />
                  <div className="min-w-0 flex-1">
                    <p style={{ color: T.text }} className="text-xs font-semibold truncate">{s.setor}</p>
                    <p style={{ color: T.subtext }} className="text-[10px]">{s.risco > 0 ? `${s.risco} em risco · ` : ""}última ronda {tempoDesde(s.ultima)}</p>
                  </div>
                  <span style={{ color: cor }} className="text-[10px] font-bold uppercase shrink-0">{s.estado === "ok" ? "Concluída" : s.estado === "parcial" ? "Parcial" : "Pendente"}</span>
                </div>
              );
            })}
            {d.rondasSetor.length === 0 && <p style={{ color: T.subtext }} className="text-xs py-8 text-center">Nenhum setor com produtos.</p>}
          </div>
        </DashCard>
      </div>

      {/* Setores, troca, atividade */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-5">
        <DashCard T={T} title="Produtos por setor" subtitle="Total monitorado e parte em risco">
          <div className="flex flex-col gap-3.5 pt-1">
            {d.setores.slice(0, 7).map((s) => (
              <div key={s.setor}>
                <div className="flex items-center justify-between text-xs mb-1.5">
                  <span style={{ color: T.text }} className="font-medium truncate pr-2">{s.setor}</span>
                  <span style={{ color: T.subtext }} className="tabular-nums shrink-0"><strong style={{ color: T.text }}>{s.total}</strong>{s.risco > 0 && <> · <span style={{ color: RED_DARK }} className="font-semibold">{s.risco} em risco</span></>}</span>
                </div>
                <div style={{ background: T.chipBg, width: `${(s.total / maxSetor) * 100}%`, minWidth: 8 }} className="h-2 rounded-full overflow-hidden">
                  <div style={{ width: `${(s.risco / s.total) * 100}%`, background: RED }} className="h-full" />
                </div>
              </div>
            ))}
            {d.setores.length === 0 && <p style={{ color: T.subtext }} className="text-xs py-8 text-center">Nenhum produto monitorado.</p>}
          </div>
        </DashCard>
        <DashCard T={T} title="Política de troca com fornecedor" subtitle="Onde a perda não volta pra loja">
          <div className="grid grid-cols-3 gap-3 pt-2">
            {[["Sem troca", d.troca.sem, RED_DARK, RED_SOFT], ["Com troca", d.troca.com, "#1F9D55", "#E6F7ED"], ["Não informado", d.troca.nao, T.subtext, T.chipBg]].map(([l, n, c, bg]) => (
              <div key={l} style={{ background: bg }} className="rounded-xl py-4 px-2 text-center">
                <p style={{ color: c }} className="text-2xl font-extrabold leading-none tabular-nums">{n}</p>
                <p style={{ color: c }} className="text-[10px] font-semibold mt-1.5">{l}</p>
              </div>
            ))}
          </div>
          <div style={{ background: T.chipBg }} className="rounded-xl p-3.5 mt-4 flex items-center justify-between">
            <span style={{ color: T.subtext }} className="text-[11px] font-semibold">Valor sem possibilidade de troca</span>
            <strong style={{ color: RED_DARK }} className="text-sm tabular-nums">{fmt(d.troca.valorSem)}</strong>
          </div>
        </DashCard>
        <DashCard T={T} title="Atividade recente" subtitle="Últimas ações da equipe"
          right={<button onClick={() => onFlow("auditoria")} style={{ color: BLUE }} className="text-[11px] font-bold hover:underline shrink-0">Auditoria →</button>}>
          <div className="flex flex-col gap-3 pt-1">
            {d.feed.map((a, k) => (
              <div key={a.id || k} className="flex items-start gap-3">
                <div style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="h-7 w-7 rounded-full flex items-center justify-center text-[10px] font-bold shrink-0">{(a.usuario || "?").trim()[0]?.toUpperCase()}</div>
                <div className="min-w-0">
                  <p style={{ color: T.text }} className="text-xs leading-snug"><strong>{a.usuario || "Alguém"}</strong> {a.acao}</p>
                  <p style={{ color: T.subtext }} className="text-[10px] mt-0.5">{formatarDataHoraExtenso(a.criadoEm)}</p>
                </div>
              </div>
            ))}
            {d.feed.length === 0 && <p style={{ color: T.subtext }} className="text-xs py-8 text-center">Nenhuma ação registrada ainda.</p>}
          </div>
        </DashCard>
      </div>
    </div>
  );
}

// ============ Toast ============
function Toast({ msg, tone }) {
  const bg = tone === "warn" ? RED_DARK : BLUE_DARK;
  return (
    <div className="fixed bottom-20 lg:bottom-6 left-1/2 lg:left-[calc(50%+8rem)] -translate-x-1/2 z-50 max-w-[90%]">
      <div style={{ background: bg }} className="text-white text-sm font-medium px-4 py-2.5 rounded-full shadow-lg flex items-center gap-2">
        <Check size={15} />{msg}
      </div>
    </div>
  );
}

// Toast com "Desfazer" — some sozinho em 5s (com contagem visual), ou a pessoa cancela antes
function DesfazerToast({ T, mensagem, onDesfazer }) {
  const [progresso, setProgresso] = useState(100);
  useEffect(() => {
    const inicio = Date.now();
    const intervalo = setInterval(() => {
      const restante = Math.max(0, 100 - ((Date.now() - inicio) / 5000) * 100);
      setProgresso(restante);
      if (restante <= 0) clearInterval(intervalo);
    }, 50);
    return () => clearInterval(intervalo);
  }, []);
  return (
    <div className="fixed bottom-20 lg:bottom-6 left-4 right-4 lg:left-72 z-50">
      <div style={{ background: "#1F2430" }} className="max-w-md mx-auto rounded-2xl px-4 py-3 shadow-lg overflow-hidden relative">
        <div style={{ width: `${progresso}%`, background: "rgba(255,255,255,0.15)" }} className="absolute inset-y-0 left-0 transition-[width] duration-75 ease-linear" />
        <div className="relative flex items-center gap-3">
          <p className="text-white text-xs font-medium flex-1">{mensagem}</p>
          <button onClick={onDesfazer} style={{ color: "#7FB2FF" }} className="text-xs font-bold shrink-0">Desfazer</button>
        </div>
      </div>
    </div>
  );
}

// ============ Home ============
// Item 33: busca "inteligente" — entende algumas expressões em linguagem natural, além de nome/código
function interpretarBusca(query, item) {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  const valor = (Number(item.quantidade) || 1) * (Number(item.precoUnitario) || 0);

  if (/vence\s*hoje|vencendo\s*hoje/.test(q)) return item.status.d === 0;
  if (/vence\s*amanh[ãa]/.test(q)) return item.status.d === 1;
  if (/venc(ido|idos)/.test(q) && !/vencendo/.test(q)) return item.status.level === "expired";
  const emDias = q.match(/vence(ndo)?\s*em\s*(\d+)\s*dias?/);
  if (emDias) return item.status.d >= 0 && item.status.d <= Number(emDias[2]);
  const acima = q.match(/acima\s*de\s*(?:r\$)?\s*(\d+)/);
  if (acima) return valor > Number(acima[1]);
  const abaixo = q.match(/abaixo\s*de\s*(?:r\$)?\s*(\d+)/);
  if (abaixo) return valor < Number(abaixo[1]);
  if (/sem\s*troca/.test(q)) return item.politicaTroca === "sem_troca";

  return item.nome.toLowerCase().includes(q) || item.barcode.includes(q);
}

// ============ Produtos monitorados — versão dashboard (PC) ============
const NIVEL_BADGE = (level) => level === "expired" ? { bg: RED_SOFT, fg: RED_DARK } : level === "alert" ? { bg: "#FDE8E8", fg: RED } : level === "warning" ? { bg: "#FCF0DD", fg: "#C2760C" } : { bg: "#E4F7EC", fg: "#1F9D55" };
function diasTexto(d) { return d < 0 ? `${Math.abs(d)} dia(s) vencido` : d === 0 ? "vence hoje" : `${d} dia(s)`; }

function TabelaProdutos({ T, itens, onOpenDetail, limite = 60, mostrarSetor = true }) {
  const fmt = useFormatarMoedaComCamada();
  const [mostrar, setMostrar] = useState(limite);
  useEffect(() => { setMostrar(limite); }, [itens.length, limite]);
  const rows = itens.slice(0, mostrar).map((i) => ({ ...i, id: i.id }));
  const cols = [
    { key: "nome", label: "Produto", render: (i) => (
      <div className="flex items-center gap-3 min-w-0">
        <Thumb foto={i.foto} size={36} />
        <div className="min-w-0"><p className="font-semibold truncate max-w-[22rem]">{i.nome}</p>{i.barcode && <p style={{ color: T.subtext }} className="text-[10.5px] font-mono">{i.barcode}</p>}</div>
      </div>) },
    ...(mostrarSetor ? [{ key: "setor", label: "Setor", render: (i) => <span style={{ color: T.subtext }}>{i.setor}</span> }] : []),
    { key: "validade", label: "Validade", render: (i) => <span className="tabular-nums">{formatarData(i.validade)}</span> },
    { key: "dias", label: "Prazo", render: (i) => { const b = NIVEL_BADGE(i.status.level); return <DashBadge bg={b.bg} color={b.fg}>{diasTexto(i.status.d)}</DashBadge>; } },
    { key: "quantidade", label: "Qtd", align: "right", render: (i) => <span className="tabular-nums">{i.quantidade ?? 1}</span> },
    { key: "valor", label: "Valor", align: "right", render: (i) => <span className="tabular-nums font-semibold">{fmt((Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0))}</span> },
    { key: "status", label: "Status", align: "right", render: (i) => { const b = statusStyles(i.status.level); return <span style={{ background: b.bg, color: b.fg }} className="text-[10px] font-bold px-2.5 py-1 rounded-full">{i.status.label}</span>; } },
  ];
  return (
    <>
      <DashTable T={T} rows={rows} cols={cols} onRow={onOpenDetail} empty="Nenhum produto encontrado." />
      {itens.length > mostrar && (
        <div className="pt-6 text-center">
          <button onClick={() => setMostrar((m) => m + 60)} style={{ background: T.chipBg, color: T.text }} className="text-xs font-semibold px-4 py-2 rounded-xl">Mostrar mais ({itens.length - mostrar} restantes)</button>
        </div>
      )}
    </>
  );
}

function DashFiltros({ T, children }) {
  return <div className="flex items-center gap-3 flex-wrap mb-4">{children}</div>;
}

function ProdutosDashboard({ T, items, historico, search, setSearch, filtroSetor, setFiltroSetor, ordenarPor, setOrdenarPor, onOpenDetail, onVerPrioridades }) {
  const fmt = useFormatarMoedaComCamada();
  const [categoria, setCategoria] = useState("todos");
  const enriched = useMemo(() => items.map((it) => ({ ...it, status: getStatus(it) })), [items]);
  const kpi = useMemo(() => {
    const val = (arr) => arr.reduce((a, i) => a + (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0), 0);
    const venc = enriched.filter((i) => i.status.level === "expired"), alerta = enriched.filter((i) => i.status.level === "alert"), aten = enriched.filter((i) => i.status.level === "warning");
    return { total: enriched.length, venc: venc.length, alerta: alerta.length, aten: aten.length, risco: val([...venc, ...alerta]) };
  }, [enriched]);
  const setores = useMemo(() => ["Todos", ...Array.from(new Set(enriched.filter((i) => categoria === "todos" || (categoria === "pereciveis" ? ehPerecivel(i.setor) : !ehPerecivel(i.setor))).map((i) => i.setor)))], [enriched, categoria]);
  const lista = useMemo(() => enriched.filter((i) => {
    if (categoria === "pereciveis" && !ehPerecivel(i.setor)) return false;
    if (categoria === "outros" && ehPerecivel(i.setor)) return false;
    if (filtroSetor !== "Todos" && i.setor !== filtroSetor) return false;
    return interpretarBusca(search, i);
  }).sort((a, b) => ordenarPor === "nome" ? a.nome.localeCompare(b.nome) : ordenarPor === "setor" ? a.setor.localeCompare(b.setor) : ordenarPor === "validade" ? b.status.d - a.status.d : a.status.d - b.status.d), [enriched, categoria, filtroSetor, search, ordenarPor]);
  const porSetor = useMemo(() => {
    const m = {};
    enriched.filter((i) => i.status.level === "alert" || i.status.level === "expired").forEach((i) => { m[i.setor] = (m[i.setor] || 0) + 1; });
    return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([label, value]) => ({ label, value, color: RED }));
  }, [enriched]);
  const donut = [{ label: "Vencidos", value: kpi.venc, color: RED_DARK }, { label: "Em alerta", value: kpi.alerta, color: RED }, { label: "Atenção", value: kpi.aten, color: "#C98A0C" }, { label: "OK", value: kpi.total - kpi.venc - kpi.alerta - kpi.aten, color: "#1F9D55" }];
  const sel = { background: T.inputBg, borderColor: T.inputBorder, color: T.text };

  return (
    <div className="hidden lg:block">
      <DashPageHeader T={T} title="Produtos monitorados" subtitle={`${kpi.total} produtos acompanhados na loja`}
        right={<button onClick={onVerPrioridades} style={{ background: T.card, borderColor: T.border, color: T.text }} className="text-xs font-semibold px-3.5 py-2 rounded-xl border">Ver prioridade de perda</button>} />
      <div className="grid grid-cols-2 xl:grid-cols-4 gap-4 mb-5">
        <DashKpi T={T} label="Total monitorado" value={kpi.total} sub="produtos com validade" Icon={Boxes} accent={BLUE} />
        <DashKpi T={T} label="Vencidos" value={kpi.venc} sub="retirar da área de venda" Icon={AlertTriangle} accent={RED_DARK} />
        <DashKpi T={T} label="Em alerta" value={kpi.alerta} sub={`${kpi.aten} em atenção`} Icon={ClockIcon} accent="#C98A0C" />
        <DashKpi T={T} label="Valor em risco" value={fmt(kpi.risco)} sub="vencidos + em alerta" Icon={TrendingDown} accent={RED} />
      </div>
      <div className="grid grid-cols-3 gap-4 mb-5">
        <DashCard T={T} title="Situação dos produtos" subtitle="Distribuição por status">
          <div className="flex items-center gap-6">
            <DashDonut T={T} size={140} thickness={20} segments={donut} centerValue={kpi.total} centerLabel="produtos" />
            <div className="flex flex-col gap-2 text-xs flex-1">
              {donut.map((s) => <div key={s.label} className="flex items-center gap-2"><i style={{ background: s.color }} className="h-2 w-2 rounded-full" /><span style={{ color: T.subtext }}>{s.label}</span><b className="ml-auto tabular-nums">{s.value}</b></div>)}
            </div>
          </div>
        </DashCard>
        <DashCard T={T} title="Críticos por setor" subtitle="Vencidos + em alerta" className="col-span-2">
          {porSetor.length ? <DashHBars T={T} data={porSetor} /> : <p style={{ color: T.subtext }} className="text-sm py-6 text-center">Nenhum produto crítico. 🎉</p>}
        </DashCard>
      </div>
      <DashCard T={T} title="Lista de produtos" subtitle={`${lista.length} resultado(s)`}
        right={<DashTabs T={T} value={categoria} onChange={(v) => { setCategoria(v); setFiltroSetor("Todos"); }} options={[{ id: "todos", label: "Todos" }, { id: "pereciveis", label: "Perecíveis" }, { id: "outros", label: "Outros" }]} />}>
        <DashFiltros T={T}>
          <div style={{ background: T.inputBg, borderColor: T.inputBorder }} className="flex items-center gap-2 border rounded-xl px-3 py-2 flex-1 min-w-[16rem]">
            <MagnifyingGlassIcon className="w-4 h-4" style={{ color: T.subtext }} />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar por nome, código, setor…" style={{ color: T.text }} className="bg-transparent outline-none text-sm flex-1" />
          </div>
          <select value={filtroSetor} onChange={(e) => setFiltroSetor(e.target.value)} style={sel} className="border rounded-xl px-3 py-2 text-sm outline-none">
            {setores.map((s) => <option key={s} value={s}>{s === "Todos" ? "Todos os setores" : s}</option>)}
          </select>
          <select value={ordenarPor} onChange={(e) => setOrdenarPor(e.target.value)} style={sel} className="border rounded-xl px-3 py-2 text-sm outline-none">
            <option value="urgencia">Mais urgentes</option><option value="validade">Validade mais longa</option><option value="nome">Nome (A–Z)</option><option value="setor">Setor</option>
          </select>
        </DashFiltros>
        <TabelaProdutos T={T} itens={lista} onOpenDetail={onOpenDetail} />
      </DashCard>
    </div>
  );
}

function HomeView({ T, items, historico, search, setSearch, filtroSetor, setFiltroSetor, ordenarPor, setOrdenarPor, modoVisual, setModoVisual, onScan, onCadastrar, onOpenDetail, onVerPrioridades, comPalco, nomeUsuario, lojaNumero, notifPermission, onToggleNotif, dark, onTema }) {
  const podeVerValores = useValoresVisiveis();
  const enriched = items.map((it) => ({ ...it, status: getStatus(it) }));
  // Item 2: perecíveis e os demais setores nunca aparecem misturados
  const [categoriaFiltro, setCategoriaFiltro] = useState("todos"); // todos | pereciveis | outros
  const [filtrosAbertos, setFiltrosAbertos] = useState(false);
  const [modoEmergencia, setModoEmergencia] = useState(false);
  const [statusFiltro, setStatusFiltro] = useState("todos"); // todos | vencido | alerta | ok
  const [trocaFiltro, setTrocaFiltro] = useState("todas"); // todas | sem_troca | com_troca | nao_informado

  // Modo emergência: o valor em risco e os contadores passam a considerar só o que vence em até 2 dias (ou já venceu).
  const baseNumeros = modoEmergencia ? enriched.filter((i) => i.status.d <= 2) : enriched;
  const valorEmRisco = baseNumeros
    .filter((i) => modoEmergencia || i.status.level === "alert" || i.status.level === "expired")
    .reduce((acc, i) => acc + (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0), 0);

  const vencidos = baseNumeros.filter((i) => i.status.level === "expired").length;
  const emAlerta = modoEmergencia ? baseNumeros.length - vencidos : baseNumeros.filter((i) => i.status.level === "alert").length;
  const total = baseNumeros.length;

  // "PRIORIDADE DE PERDA": resumo pro card do dashboard — a lista completa mora na aba Prioridade Inteligente
  const resumoPrioridade = useMemo(() => {
    const todas = items
      .map((it) => ({ item: it, p: calcularPrioridade(it, historico) }))
      .filter((x) => x.p && (x.p.status.level === "alert" || x.p.status.level === "expired"));
    const semTroca = todas.filter((x) => x.p.semTroca);
    const valorEmRisco = todas.reduce((acc, x) => acc + x.p.valor, 0);
    const porSetor = {};
    todas.forEach((x) => { porSetor[x.item.setor] = (porSetor[x.item.setor] || 0) + 1; });
    const topSetores = Object.entries(porSetor).sort((a, b) => b[1] - a[1]).slice(0, 4);
    return { total: todas.length, semTroca: semTroca.length, valorEmRisco, topSetores };
  }, [items, historico]);

  // Item 18: comparação com troca × sem troca × não informado
  const comparativoTroca = useMemo(() => {
    let comTroca = 0, semTroca = 0, naoInformado = 0, valorSemTroca = 0;
    items.forEach((i) => {
      if (i.politicaTroca === "sem_troca") { semTroca++; valorSemTroca += (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0); }
      else if (i.politicaTroca === "com_troca") comTroca++;
      else naoInformado++;
    });
    return { comTroca, semTroca, naoInformado, valorSemTroca };
  }, [items]);

  const itensNaCategoria = items.filter((i) => categoriaFiltro === "todos" || (categoriaFiltro === "pereciveis" ? ehPerecivel(i.setor) : !ehPerecivel(i.setor)));
  const setoresDisponiveis = ["Todos", ...Array.from(new Set(itensNaCategoria.map((i) => i.setor)))];
  const filtrosAtivos = (categoriaFiltro !== "todos" ? 1 : 0) + (filtroSetor !== "Todos" ? 1 : 0) + (ordenarPor !== "urgencia" ? 1 : 0) + (trocaFiltro !== "todas" ? 1 : 0);
  const politicaDe = (i) => (i.politicaTroca === "sem_troca" || i.politicaTroca === "com_troca" ? i.politicaTroca : "nao_informado");
  const nivelDe = (i) => (i.status.level === "expired" ? "vencido" : i.status.level === "alert" ? "alerta" : "ok");
  const passaBase = (i) => {
    if (categoriaFiltro === "pereciveis" && !ehPerecivel(i.setor)) return false;
    if (categoriaFiltro === "outros" && ehPerecivel(i.setor)) return false;
    if (modoEmergencia && i.status.d > 2) return false;
    if (filtroSetor !== "Todos" && i.setor !== filtroSetor) return false;
    if (trocaFiltro !== "todas" && politicaDe(i) !== trocaFiltro) return false;
    try { return interpretarBusca(search, i); } catch { return true; }
  };
  const baseLista = enriched.filter(passaBase);
  const contagemStatus = { todos: baseLista.length, vencido: baseLista.filter((i) => nivelDe(i) === "vencido").length, alerta: baseLista.filter((i) => nivelDe(i) === "alerta").length, ok: baseLista.filter((i) => nivelDe(i) === "ok").length };
  const limparFiltros = () => { setCategoriaFiltro("todos"); setFiltroSetor("Todos"); setOrdenarPor("urgencia"); setTrocaFiltro("todas"); setStatusFiltro("todos"); };

  let filtrados = baseLista.filter((i) => statusFiltro === "todos" || nivelDe(i) === statusFiltro);

  filtrados = filtrados.sort((a, b) => {
    if (ordenarPor === "urgencia") return a.status.d - b.status.d;
    if (ordenarPor === "nome") return a.nome.localeCompare(b.nome);
    if (ordenarPor === "setor") return a.setor.localeCompare(b.setor);
    if (ordenarPor === "validade") return b.status.d - a.status.d;
    return 0;
  });

  const trocaTotal = comparativoTroca.semTroca + comparativoTroca.comTroca + comparativoTroca.naoInformado;
  const mostrarPrioridade = !modoEmergencia && resumoPrioridade.total > 0;
  const mostrarTroca = !modoEmergencia && trocaTotal > 0;
  const pontoTroca = (cor) => <span style={{ background: cor }} className="h-2 w-2 rounded-full shrink-0" />;

  return (
    <div>
      {comPalco && (
        <PalcoInicio logo={LOGO_SRC} nome={nomeUsuario} loja={lojaNumero} valorNum={valorEmRisco} formatarMoeda={formatarMoeda}
          vencidos={vencidos} alerta={emAlerta} total={total} emergencia={modoEmergencia} onEmergencia={() => setModoEmergencia((v) => !v)}
          notifOk={notifPermission === "granted"} onNotif={onToggleNotif} dark={dark} onTema={onTema} />
      )}
      <div style={{ background: T.bg }} className={`relative z-10 px-4 ${comPalco ? "-mt-7 rounded-t-[32px] pt-6" : "pt-4"}`}>
      {(mostrarPrioridade || mostrarTroca) && (
        <div className={`grid gap-3 mb-5 ${mostrarPrioridade && mostrarTroca ? "grid-cols-2" : "grid-cols-1"}`}>
          {mostrarPrioridade && (
            <motion.button initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }} whileTap={{ scale: 0.97 }} onClick={onVerPrioridades}
              style={{ background: T.card }} className="text-left rounded-[24px] p-4 shadow-lg shadow-black/5 flex flex-col">
              <div className="flex items-center justify-between">
                <span style={{ background: RED_SOFT }} className="h-9 w-9 rounded-2xl flex items-center justify-center"><FireIconSolid className="w-[18px] h-[18px]" style={{ color: RED_DARK }} /></span>
                <ChevronRightIcon className="w-4 h-4" style={{ color: T.subtext }} />
              </div>
              <p style={{ color: T.subtext }} className="text-[11px] font-bold uppercase tracking-wide mt-3">Prioridade de perda</p>
              <p style={{ color: T.text }} className="text-[26px] font-extrabold leading-tight tabular-nums">{resumoPrioridade.total}</p>
              <p style={{ color: T.subtext }} className="text-[11.5px] leading-snug">{resumoPrioridade.semTroca > 0 ? `${resumoPrioridade.semTroca} sem troca` : "precisam de atenção"}</p>
              <div className="flex flex-col gap-1 mt-2.5">
                {resumoPrioridade.topSetores.slice(0, 3).map(([setor, n]) => (
                  <p key={setor} style={{ color: T.text }} className="text-[12px] font-semibold flex items-center justify-between gap-2"><span className="truncate">{setor}</span><span style={{ background: RED_SOFT, color: RED_DARK }} className="text-[10.5px] font-bold rounded-full px-2 py-0.5 tabular-nums shrink-0">{n}</span></p>
                ))}
              </div>
            </motion.button>
          )}
          {mostrarTroca && (
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.18 }}
              style={{ background: T.card }} className="rounded-[24px] p-4 shadow-lg shadow-black/5 flex flex-col">
              <span style={{ background: BLUE_SOFT }} className="h-9 w-9 rounded-2xl flex items-center justify-center"><ShieldCheckIcon className="w-[18px] h-[18px]" style={{ color: BLUE }} /></span>
              <p style={{ color: T.subtext }} className="text-[11px] font-bold uppercase tracking-wide mt-3">Troca com fornecedor</p>
              <div className="flex flex-col gap-1.5 mt-1.5">
                <p style={{ color: T.text }} className="text-[13px] font-bold flex items-center gap-2 tabular-nums">{pontoTroca(RED_DARK)}{comparativoTroca.semTroca}<span style={{ color: T.subtext }} className="font-medium text-[11.5px]">sem troca</span></p>
                <p style={{ color: T.text }} className="text-[13px] font-bold flex items-center gap-2 tabular-nums">{pontoTroca("#1F9D55")}{comparativoTroca.comTroca}<span style={{ color: T.subtext }} className="font-medium text-[11.5px]">com troca</span></p>
                <p style={{ color: T.text }} className="text-[13px] font-bold flex items-center gap-2 tabular-nums">{pontoTroca("#9AA3B2")}{comparativoTroca.naoInformado}<span style={{ color: T.subtext }} className="font-medium text-[11.5px]">não informado</span></p>
              </div>
              {comparativoTroca.valorSemTroca > 0 && <p style={{ color: RED_DARK }} className="text-[11px] font-bold mt-2">{formatarMoeda(comparativoTroca.valorSemTroca)} sem troca</p>}
            </motion.div>
          )}
        </div>
      )}

      <section className="min-w-0">
      {/* Busca + filtros: tudo numa faixa só, com contagem ao vivo */}
      <div className="flex gap-2 mb-3">
        <div className="flex-1 relative">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2" color={T.subtext} />
          <input value={search} onChange={(e) => setSearch(sanitizarTexto(e.target.value, 80))} placeholder="Buscar produto ou código..." enterKeyHint="search"
            style={{ background: T.card, color: T.text, borderColor: T.inputBorder }} className="w-full rounded-full pl-11 pr-10 py-3 text-sm border outline-none focus:ring-2 shadow-sm" />
          {search && <button onClick={() => setSearch("")} aria-label="Limpar busca" style={{ background: T.chipBg }} className="absolute right-2.5 top-1/2 -translate-y-1/2 h-6 w-6 rounded-full flex items-center justify-center"><CloseIcon size={12} color={T.subtext} /></button>}
        </div>
        <motion.button whileTap={{ scale: 0.92 }} onClick={() => setFiltrosAbertos(true)} aria-label="Filtros" style={{ background: filtrosAtivos > 0 ? BLUE_DARK : T.card, color: filtrosAtivos > 0 ? "#fff" : T.text }}
          className="h-[46px] w-[46px] rounded-full flex items-center justify-center shrink-0 relative shadow-sm">
          <SlidersHorizontal size={17} />
          {filtrosAtivos > 0 && <span style={{ background: RED }} className="absolute -top-1 -right-1 text-[9px] text-white font-bold rounded-full h-4 min-w-[16px] px-1 flex items-center justify-center">{filtrosAtivos}</span>}
        </motion.button>
        <motion.button whileTap={{ scale: 0.92 }} onClick={() => setModoVisual(modoVisual === "lista" ? "grade" : "lista")} aria-label="Trocar lista e grade"
          style={{ background: T.card, color: T.text }} className="h-[46px] w-[46px] rounded-full flex items-center justify-center shrink-0 shadow-sm">
          {modoVisual === "lista" ? <LayoutGrid size={17} /> : <ListIcon size={17} />}
        </motion.button>
      </div>

      <div className="flex gap-1.5 overflow-x-auto no-scrollbar pb-1 mb-3">
        {[["todos", "Todos", T.text], ["vencido", "Vencidos", "#E31E24"], ["alerta", "Em alerta", "#E0921C"], ["ok", "Em dia", "#1F9D55"]].map(([id, rot, cor]) => {
          const ativo = statusFiltro === id;
          return (
            <motion.button key={id} whileTap={{ scale: 0.94 }} onClick={() => setStatusFiltro(id)} aria-pressed={ativo}
              style={ativo ? { background: BLUE_DARK, color: "#fff" } : { background: T.card, color: T.text }} className="shrink-0 rounded-full pl-3 pr-2.5 py-2 text-xs font-bold flex items-center gap-1.5 shadow-sm">
              {id !== "todos" && <span className="h-2 w-2 rounded-full" style={{ background: cor }} />}{rot}
              <span style={ativo ? { background: "rgba(255,255,255,.22)", color: "#fff" } : { background: T.chipBg, color: T.subtext }} className="text-[10.5px] font-bold rounded-full px-1.5 min-w-[20px] text-center tabular-nums">{contagemStatus[id]}</span>
            </motion.button>
          );
        })}
      </div>

      {(categoriaFiltro !== "todos" || filtroSetor !== "Todos" || trocaFiltro !== "todas" || ordenarPor !== "urgencia") && (
        <div className="flex items-center gap-1.5 flex-wrap mb-3">
          {categoriaFiltro !== "todos" && <FichaFiltro onRemove={() => setCategoriaFiltro("todos")}>{categoriaFiltro === "pereciveis" ? "Perecíveis" : "Outros setores"}</FichaFiltro>}
          {filtroSetor !== "Todos" && <FichaFiltro onRemove={() => setFiltroSetor("Todos")}>{filtroSetor}</FichaFiltro>}
          {trocaFiltro !== "todas" && <FichaFiltro onRemove={() => setTrocaFiltro("todas")}>{trocaFiltro === "sem_troca" ? "Sem troca" : trocaFiltro === "com_troca" ? "Com troca" : "Troca não informada"}</FichaFiltro>}
          {ordenarPor !== "urgencia" && <FichaFiltro onRemove={() => setOrdenarPor("urgencia")}>Ordem: {{ nome: "nome", setor: "setor", validade: "validade distante" }[ordenarPor]}</FichaFiltro>}
          <button onClick={limparFiltros} style={{ color: T.subtext }} className="text-[11.5px] font-bold underline px-1">Limpar tudo</button>
        </div>
      )}

      {createPortal(<AnimatePresence>
        {filtrosAbertos && (
          <motion.div className="fixed inset-0 z-[60] flex items-end justify-center" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <div onClick={() => setFiltrosAbertos(false)} className="absolute inset-0 bg-black/55" />
            <motion.div initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} transition={{ type: "spring", stiffness: 380, damping: 38 }}
              style={{ background: T.card }} className="relative w-full max-w-md rounded-t-[30px] flex flex-col max-h-[calc(100dvh-env(safe-area-inset-top)-1rem)] overflow-hidden">
              <div style={{ background: FUNDO_MARCA }} className="relative shrink-0 px-5 pt-3 pb-4 text-white">
                <div aria-hidden className="absolute inset-0 opacity-[.13]" style={{ backgroundImage: "radial-gradient(#fff 1px, transparent 1.4px)", backgroundSize: "20px 20px" }} />
                <div className="relative mx-auto h-1 w-10 rounded-full bg-white/40 mb-3" />
                <div className="relative flex items-center justify-between">
                  <div><h3 className="font-extrabold text-[18px] leading-tight">Filtros</h3><p className="text-[12px] text-white/75">{filtrados.length} produto{filtrados.length !== 1 ? "s" : ""} com a seleção atual</p></div>
                  <button onClick={() => setFiltrosAbertos(false)} aria-label="Fechar" className="h-9 w-9 rounded-full flex items-center justify-center" style={{ background: "rgba(255,255,255,.18)" }}><CloseIcon size={16} color="#fff" /></button>
                </div>
              </div>
              <div className="flex-1 min-h-0 overflow-y-auto overscroll-contain px-5 pt-4">
                <GrupoFiltro T={T} titulo="Categoria" opcoes={[["todos", "Todos"], ["pereciveis", "Perecíveis"], ["outros", "Outros setores"]]} valor={categoriaFiltro} onChange={(v) => { setCategoriaFiltro(v); setFiltroSetor("Todos"); }} />
                {setoresDisponiveis.length > 1 && <GrupoFiltro T={T} titulo="Setor" opcoes={setoresDisponiveis.map((x) => [x, x])} valor={filtroSetor} onChange={setFiltroSetor} />}
                <GrupoFiltro T={T} titulo="Política de troca" opcoes={[["todas", "Todas"], ["sem_troca", "Sem troca"], ["com_troca", "Com troca"], ["nao_informado", "Não informada"]]} valor={trocaFiltro} onChange={setTrocaFiltro} />
                <GrupoFiltro T={T} titulo="Ordenar por" opcoes={[["urgencia", "Urgência"], ["nome", "Nome"], ["setor", "Setor"], ["validade", "Validade distante"]]} valor={ordenarPor} onChange={setOrdenarPor} />
              </div>
              <div style={{ borderColor: T.border }} className="shrink-0 flex gap-2 px-5 pt-3 pb-[calc(1rem+env(safe-area-inset-bottom))] border-t">
                <button onClick={limparFiltros} style={{ background: T.chipBg, color: T.text }} className="flex-1 text-sm font-bold py-3.5 rounded-2xl">Limpar</button>
                <button onClick={() => setFiltrosAbertos(false)} style={{ background: `linear-gradient(135deg, ${BLUE} 0%, ${BLUE_DARK} 100%)`, color: "#fff" }} className="flex-[2] text-sm font-extrabold py-3.5 rounded-2xl">Ver {filtrados.length} produto{filtrados.length !== 1 ? "s" : ""}</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>, document.body)}

      {filtrados.length === 0 ? (
        <EmptyState T={T} hasItems={items.length > 0} />
      ) : (
        <>
          <div className="flex items-center justify-between mb-2.5">
            <p style={{ color: T.text }} className="text-[15px] font-extrabold">Produtos monitorados <span style={{ background: T.chipBg, color: T.subtext }} className="ml-1 text-[11px] font-bold rounded-full px-2 py-0.5 tabular-nums align-middle">{filtrados.length}</span></p>
          </div>
          {modoVisual === "lista" ? (
            <div className="flex flex-col gap-2.5 xl:grid xl:grid-cols-2 2xl:grid-cols-3 xl:items-start">
              {agruparItensPorProduto(filtrados).map((g, i) => (
                <LinhaProduto key={g.unico ? g.item.id : `grupo-${i}`} T={T} idx={i} mostrarSetor podeVerValores={podeVerValores}
                  item={g.unico ? g.item : g.base} lotes={g.unico ? null : g.lotes} totalQuantidade={g.totalQuantidade} piorStatus={g.unico ? g.item.status : g.piorStatus} onOpenDetail={onOpenDetail} />
              ))}
            </div>
          ) : (
            <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-2.5">
              {filtrados.map((item, i) => <CartaoGrade key={item.id} T={T} item={item} idx={i} onOpenDetail={onOpenDetail} />)}
            </div>
          )}
        </>
      )}
      </section>
      </div>
    </div>
  );
}

function FichaFiltro({ children, onRemove }) {
  return (
    <span style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-[11.5px] font-bold pl-2.5 pr-1.5 py-1 rounded-full flex items-center gap-1">
      {children}
      <button onClick={onRemove} aria-label="Remover filtro" className="h-4 w-4 rounded-full flex items-center justify-center" style={{ background: "rgba(11,79,158,.15)" }}><CloseIcon size={9} color={BLUE_DARK} /></button>
    </span>
  );
}
function GrupoFiltro({ T, titulo, opcoes, valor, onChange }) {
  return (
    <div className="mb-5">
      <p style={{ color: T.subtext }} className="text-[11px] font-bold uppercase tracking-[.1em] mb-2">{titulo}</p>
      <div className="flex gap-1.5 flex-wrap">
        {opcoes.map(([id, rot]) => (
          <motion.button key={id} whileTap={{ scale: 0.94 }} onClick={() => onChange(id)} aria-pressed={valor === id}
            style={valor === id ? { background: BLUE_DARK, color: "#fff" } : { background: T.chipBg, color: T.text }} className="text-[12.5px] font-bold px-3.5 py-2 rounded-full">{rot}</motion.button>
        ))}
      </div>
    </div>
  );
}

function StatCard({ T, label, value, color }) {
  return (
    <div style={{ background: T.card }} className="rounded-[22px] px-3 py-3.5 shadow-lg shadow-black/5 text-center">
      <p style={{ color }} className="text-2xl font-extrabold leading-none tabular-nums">{value}</p>
      <p style={{ color: T.subtext }} className="text-[11px] mt-1.5 font-bold">{label}</p>
    </div>
  );
}

function EmptyState({ T, hasItems }) {
  const ehDesktop = useDesktop();
  return (
    <EstadoVazioNovo T={T} Icone={Package} titulo={hasItems ? "Nada encontrado" : "Nenhum produto monitorado"}
      texto={hasItems ? "Ajuste a busca ou os filtros." : (ehDesktop ? "Os produtos aparecem aqui quando a equipe cadastra os alertas de validade pelo celular." : 'Toque em "Bipar produto" para começar a cadastrar alertas de validade.')} />
  );
}

function Thumb({ foto, size = 44, rounded = "rounded-xl" }) {
  return foto ? (
    <img src={foto} alt="" style={{ width: size, height: size }} className={`${rounded} object-cover shrink-0`} />
  ) : (
    <div style={{ width: size, height: size, background: BLUE_SOFT }} className={`${rounded} flex items-center justify-center shrink-0`}>
      <Package size={size * 0.42} color={BLUE} />
    </div>
  );
}

function ItemCard({ T, item, onOpenDetail }) {
  const podeVerValores = useValoresVisiveis();
  const s = statusStyles(item.status.level);
  const desconto = sugestaoDesconto(item.status.d, item.precoUnitario);
  let diasTexto;
  if (item.status.level === "expired") diasTexto = `Vencido há ${Math.abs(item.status.d)} dia${Math.abs(item.status.d) === 1 ? "" : "s"}`;
  else if (item.status.d === 0) diasTexto = "Vence hoje";
  else diasTexto = `Vence em ${item.status.d} dia${item.status.d === 1 ? "" : "s"}`;

  return (
    <button onClick={() => onOpenDetail(item)} style={{ background: T.card, borderColor: T.border }} className="rounded-2xl p-3.5 shadow-lg shadow-black/5 border text-left w-full active:scale-[0.99] transition">
      <div className="flex items-start gap-3">
        <Thumb foto={item.foto} size={48} />
        <div className="flex-1 min-w-0">
          <p className="font-semibold text-sm truncate">{item.nome}</p>
          <div className="flex items-center gap-1.5 mt-0.5 flex-wrap">
            <span style={{ color: T.subtext }} className="inline-flex items-center gap-1 text-[11px]"><MapPin size={11} /> {item.setor}</span>
            <span style={{ color: T.subtext }} className="text-[11px]">•</span>
            <span style={{ color: T.subtext }} className="inline-flex items-center gap-1 text-[11px] font-mono"><Barcode size={11} /> {item.barcode}</span>
          </div>
          <div className="flex items-center gap-2 mt-2 flex-wrap">
            <span style={{ background: s.bg, color: s.fg }} className="text-[10px] font-bold px-2 py-1 rounded-md tracking-wide">{item.status.label}</span>
            <span className="text-[11px] font-medium">{diasTexto}</span>
            {desconto && (
              <span style={{ background: RED_SOFT, color: RED_DARK }} className="inline-flex items-center gap-0.5 text-[10px] font-bold px-1.5 py-1 rounded-md">
                <Percent size={10} /> {desconto.pct}% sugerido
              </span>
            )}
            {item.politicaTroca === "sem_troca" && (
              <span style={{ background: "#4A1013", color: "#FFD5D8" }} className="inline-flex items-center gap-0.5 text-[10px] font-bold px-1.5 py-1 rounded-md">
                <ShieldAlert size={10} /> SEM TROCA
              </span>
            )}
          </div>
          <p style={{ color: T.subtext }} className="text-[10px] mt-1.5">
            Validade {formatarData(item.validade)} · alerta {[item.diasAlerta, ...(item.diasAlertaExtras || [])].sort((a, b) => b - a).join("/")}d
            {item.quantidade ? ` · qtd ${item.quantidade}${item.porPeso ? "kg" : ""}` : ""}
            {item.precoUnitario && podeVerValores ? ` · ${formatarMoeda(item.precoUnitario)}${item.porPeso ? "/kg" : "/un"}` : ""}
          </p>
          {gerarCodigoLocalizacao(item) && <p style={{ color: T.subtext }} className="text-[10px] mt-0.5 font-mono flex items-center gap-1"><MapPin size={9} /> {gerarCodigoLocalizacao(item)}</p>}
          {item.cadastradoPor && <p style={{ color: T.subtext }} className="text-[10px] mt-0.5">Cadastrado por {item.cadastradoPor}</p>}
        </div>
        <ChevronRight size={16} color={T.subtext} className="shrink-0 mt-1" />
      </div>
    </button>
  );
}

function ItemCardAgrupado({ T, base, lotes, totalQuantidade, piorStatus, onOpenDetail }) {
  const [aberto, setAberto] = useState(false);
  const s = statusStyles(piorStatus.level);
  const temDeposito = lotes.some((l) => l.local === "deposito");
  const temLoja = lotes.some((l) => (l.local || "loja") === "loja");

  return (
    <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl shadow-lg shadow-black/5 border overflow-hidden">
      <button onClick={() => setAberto((v) => !v)} className="w-full text-left p-3.5">
        <div className="flex items-start gap-3">
          <Thumb foto={base.foto} size={48} />
          <div className="flex-1 min-w-0">
            <p className="font-semibold text-sm truncate">{base.nome}</p>
            <div className="flex items-center gap-1.5 mt-0.5 flex-wrap">
              <span style={{ color: T.subtext }} className="inline-flex items-center gap-1 text-[11px]"><MapPin size={11} /> {base.setor}</span>
              <span style={{ color: T.subtext }} className="text-[11px]">•</span>
              <span style={{ color: T.subtext }} className="inline-flex items-center gap-1 text-[11px] font-mono"><Barcode size={11} /> {base.barcode}</span>
            </div>
            <div className="flex items-center gap-2 mt-2 flex-wrap">
              <span style={{ background: s.bg, color: s.fg }} className="text-[10px] font-bold px-2 py-1 rounded-md tracking-wide">{piorStatus.label}</span>
              <span style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-[10px] font-bold px-2 py-1 rounded-md">{lotes.length} datas diferentes</span>
            </div>
            <p style={{ color: T.subtext }} className="text-[10px] mt-1.5">Total {totalQuantidade} unidade{totalQuantidade !== 1 ? "s" : ""} nesse produto</p>
          </div>
          <ChevronRight size={16} color={T.subtext} className={`shrink-0 mt-1 transition-transform ${aberto ? "rotate-90" : ""}`} />
        </div>
      </button>
      {aberto && (
        <div style={{ borderColor: T.border }} className="border-t px-3.5 py-2.5 flex flex-col gap-2">
          {lotes.map((l) => {
            const sl = statusStyles(l.status.level);
            return (
              <button key={l.id} onClick={() => onOpenDetail(l)} style={{ background: T.chipBg }} className="w-full text-left rounded-xl p-2.5 flex items-center justify-between gap-2">
                <div className="min-w-0">
                  <div className="flex items-center gap-1.5">
                    <span style={{ background: sl.bg, color: sl.fg }} className="text-[9px] font-bold px-1.5 py-0.5 rounded">{sl.label}</span>
                    <span className="text-xs font-semibold">{formatarData(l.validade)}</span>
                    <span style={{ color: T.subtext }} className="text-[10px]">· {l.quantidade || 1} un</span>
                  </div>
                  {gerarCodigoLocalizacao(l) && <p style={{ color: T.subtext }} className="text-[10px] mt-0.5 font-mono">{gerarCodigoLocalizacao(l)}</p>}
                </div>
                <ChevronRight size={14} color={T.subtext} className="shrink-0" />
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ItemCardGrid({ T, item, onOpenDetail }) {
  const s = statusStyles(item.status.level);
  return (
    <motion.button whileTap={{ scale: 0.97 }} onClick={() => onOpenDetail(item)} style={{ background: T.card }}
      className="rounded-2xl overflow-hidden shadow-lg shadow-black/5 text-left">
      <div className="relative">
        {item.foto ? <img src={item.foto} alt="" className="w-full h-24 object-cover" /> : (
          <div style={{ background: BLUE_SOFT }} className="w-full h-24 flex items-center justify-center"><Package size={26} color={BLUE} /></div>
        )}
        <span style={{ background: s.bg, color: s.fg }} className="absolute top-1.5 left-1.5 text-[9px] font-bold px-1.5 py-0.5 rounded-md">{item.status.label}</span>
      </div>
      <div className="p-2.5">
        <p className="font-semibold text-xs truncate">{item.nome}</p>
        <p style={{ color: T.subtext }} className="text-[10px] mt-0.5 truncate flex items-center gap-1"><MapPin size={9} /> {item.setor}</p>
        <p style={{ color: T.subtext }} className="text-[10px] mt-1 flex items-center gap-1"><Calendar size={9} /> {formatarData(item.validade)}</p>
      </div>
    </motion.button>
  );
}

// ============ Modal de detalhe do produto ============
function ProductDetailModal({ T, item, outrosLotes, onTrocarLote, onClose, onEdit, onDuplicate, onBaixa, onShare, onAplicarPromocao, onExcluir }) {
  const podeVerValores = useValoresVisiveis();
  const [confirmandoBaixa, setConfirmandoBaixa] = useState(false);
  const [subEtapa, setSubEtapa] = useState(null); // null | 'promocao' | 'quantidadeFinal'
  const [motivoPendente, setMotivoPendente] = useState(null);
  const [precoPromoInput, setPrecoPromoInput] = useState(item.precoPromocional ? String(item.precoPromocional) : "");
  const [quantidadeFinalInput, setQuantidadeFinalInput] = useState(String(item.quantidade || 1));
  const [confirmandoExclusao, setConfirmandoExclusao] = useState(false);
  const [motivoExclusao, setMotivoExclusao] = useState(null);
  const [motivoExclusaoOutro, setMotivoExclusaoOutro] = useState("");
  const [historicoValidade, setHistoricoValidade] = useState(null);
  const [mostrarHistoricoValidade, setMostrarHistoricoValidade] = useState(false);
  useEffect(() => { supaFetchAlteracoesValidade(item.barcode).then(setHistoricoValidade); }, [item.barcode]);
  const status = getStatus(item);
  const s = statusStyles(status.level);
  const desconto = descontoSugerido(item, status);
  let diasTexto;
  if (status.level === "expired") diasTexto = `Vencido há ${Math.abs(status.d)} dia${Math.abs(status.d) === 1 ? "" : "s"}`;
  else if (status.d === 0) diasTexto = "Vence hoje";
  else diasTexto = `Vence em ${status.d} dia${status.d === 1 ? "" : "s"}`;

  function escolherMotivo(m) {
    if (m === "Promoção aplicada" && !item.emPromocao) { setSubEtapa("promocao"); return; }
    setMotivoPendente(m);
    setQuantidadeFinalInput(String(item.quantidade || 1));
    setSubEtapa("quantidade");
  }

  return (
    <>
    <div className="fixed inset-0 z-40 flex items-end justify-center sm:items-center">
      <div onClick={onClose} className="absolute inset-0 bg-black/50" />
      <motion.div initial={{ y: "100%" }} animate={{ y: 0 }} transition={{ type: "spring", stiffness: 380, damping: 38 }}
        style={{ background: T.card }} className="relative w-full max-w-md lg:max-w-xl lg:ring-1 lg:ring-black/10 lg:shadow-2xl rounded-t-[30px] overflow-hidden flex flex-col max-h-[calc(100dvh-env(safe-area-inset-top)-0.75rem)] sm:max-h-[90vh] sm:rounded-[30px]">
        <div className="relative shrink-0">
          {item.foto ? <img src={item.foto} alt="" className="w-full h-36 object-cover" /> : (
            <div style={{ background: FUNDO_MARCA }} className="relative w-full h-28 flex items-center justify-center"><div aria-hidden className="absolute inset-0 opacity-[.13]" style={{ backgroundImage: "radial-gradient(#fff 1px, transparent 1.4px)", backgroundSize: "20px 20px" }} /><Package size={44} color="#fff" className="relative opacity-90" /></div>
          )}
          <button onClick={onClose} aria-label="Fechar" className="absolute top-3 left-3 h-10 w-10 rounded-full flex items-center justify-center text-white" style={{ background: "rgba(255,255,255,.2)", backdropFilter: "blur(10px)", WebkitBackdropFilter: "blur(10px)", border: "1px solid rgba(255,255,255,.3)" }}><ArrowLeftIcon className="w-4 h-4 text-white" /></button>
          <span style={{ background: s.bg, color: s.fg }} className="absolute bottom-3 left-4 text-[11px] font-bold px-3 py-1 rounded-full shadow-md">{status.label}</span>
        </div>

        <div className="flex-1 min-h-0 overflow-y-auto overscroll-contain p-4">
          <h2 className="font-bold text-lg leading-tight">{item.nome}</h2>
          <p style={{ color: T.subtext }} className="text-sm font-medium mt-0.5">{diasTexto}{item.tamanho ? ` · ${item.tamanho}${item.unidadeMedida || ""}` : ""}</p>

          {/* Dados essenciais em grade simples — sem elementos decorativos */}
          <div style={{ background: T.chipBg }} className="rounded-2xl mt-3.5 p-3.5 grid grid-cols-2 gap-3">
            <div>
              <p style={{ color: T.subtext }} className="text-[9px] font-bold uppercase tracking-wide mb-0.5">Setor</p>
              <p className="text-[13px] font-bold truncate">{item.setor}{item.subsetor ? ` · ${item.subsetor}` : ""}</p>
            </div>
            <div className="text-right">
              <p style={{ color: T.subtext }} className="text-[9px] font-bold uppercase tracking-wide mb-0.5">Validade</p>
              <p className="text-[13px] font-bold">{formatarData(item.validade)}</p>
            </div>
            <div className="col-span-2 pt-2.5 border-t" style={{ borderColor: T.border }}>
              <p style={{ color: T.subtext }} className="text-[9px] font-bold uppercase tracking-wide mb-0.5 flex items-center gap-1"><Barcode size={11} /> Código do produto</p>
              <p style={{ color: T.text }} className="text-[13px] font-mono font-semibold tracking-wide">{item.barcode}</p>
            </div>
          </div>

          {item.emPromocao && (
            <div style={{ background: BLUE_SOFT }} className="rounded-2xl px-3.5 py-3 mt-3 flex items-center gap-2.5">
              <Percent size={15} color={BLUE} />
              <div>
                <p style={{ color: BLUE_DARK }} className="text-xs font-bold">Em promoção</p>
                <p style={{ color: BLUE }} className="text-[11px]">{formatarMoeda(item.precoPromocional)} <span className="line-through opacity-60">{formatarMoeda(item.precoUnitario)}</span></p>
              </div>
            </div>
          )}

          {desconto && !item.emPromocao && (
            <div style={{ background: RED_SOFT }} className="rounded-2xl px-3.5 py-3 mt-3">
              <div className="flex items-center gap-2.5">
                <div style={{ background: "rgba(255,255,255,0.6)" }} className="h-7 w-7 rounded-full flex items-center justify-center shrink-0"><Percent size={14} color={RED_DARK} /></div>
                <p style={{ color: RED_DARK }} className="text-xs font-bold">{desconto.label} · {desconto.pct}% OFF sugerido</p>
              </div>
              {desconto.precoOriginal && (
                <div className="flex items-center gap-2 mt-2 pl-9">
                  <span style={{ color: RED_DARK }} className="text-xs line-through opacity-60">{formatarMoeda(desconto.precoOriginal)}</span>
                  <span style={{ color: RED_DARK }} className="text-sm font-extrabold">{formatarMoeda(desconto.precoComDesconto)}</span>
                  <span style={{ color: RED_DARK }} className="text-[10px] opacity-70">/un sugerido</span>
                </div>
              )}
            </div>
          )}

          <div className="grid grid-cols-2 gap-2.5 mt-3.5">
            <InfoTile T={T} icon={Clock} label="Alerta" value={[item.diasAlerta, ...(item.diasAlertaExtras || [])].sort((a, b) => b - a).join(", ") + " dias antes"} />
            {!!item.quantidade && <InfoTile T={T} icon={Layers} label="Quantidade" value={item.porPeso ? `${item.quantidade} kg` : item.quantidade} />}
            {!!item.precoUnitario && podeVerValores && <InfoTile T={T} icon={DollarSign} label={item.porPeso ? "Valor total (kg)" : "Valor total"} value={formatarMoeda((item.quantidade || 1) * item.precoUnitario)} />}
            {item.familia && <InfoTile T={T} icon={Boxes} label="Família" value={item.familia} />}
            {gerarCodigoLocalizacao(item) && <InfoTile T={T} icon={Target} label="Localização" value={gerarCodigoLocalizacao(item)} mono />}
            {item.categoriaGiro && <InfoTile T={T} icon={TrendingDown} label="Giro" value={item.categoriaGiro} />}
            {item.politicaTroca && (
              <InfoTile T={T} icon={ShieldAlert} label="Política de troca" value={item.politicaTroca === "sem_troca" ? "Sem troca" : "Com troca"} />
            )}
          </div>

          {(item.cadastradoPor || item.atualizadoPor) && (
            <div style={{ background: T.chipBg }} className="rounded-xl px-3 py-2.5 mt-3 flex items-center gap-2">
              <Users2 size={13} color={T.subtext} />
              <p style={{ color: T.subtext }} className="text-[11px]">
                {item.cadastradoPor && <>Cadastrado por <strong style={{ color: T.text }}>{item.cadastradoPor}</strong></>}
                {item.atualizadoPor && item.atualizadoPor !== item.cadastradoPor && <> · editado por <strong style={{ color: T.text }}>{item.atualizadoPor}</strong></>}
              </p>
            </div>
          )}

          {item.observacoes && (
            <div style={{ background: T.chipBg }} className="rounded-xl px-3 py-2.5 mt-3">
              <p style={{ color: T.subtext }} className="text-[10px] font-semibold uppercase mb-0.5">Observações</p>
              <p className="text-sm">{item.observacoes}</p>
            </div>
          )}

          {/* Outros lotes/validades do mesmo produto neste setor — antes só dava pra ver isso na listagem do setor */}
          {outrosLotes && outrosLotes.length > 0 && (
            <div style={{ background: T.chipBg }} className="rounded-2xl mt-3.5 p-3">
              <p style={{ color: T.subtext }} className="text-[10px] font-bold uppercase tracking-wide mb-2 flex items-center gap-1.5"><Layers size={12} /> Outros lotes deste produto ({outrosLotes.length})</p>
              <div className="flex flex-col gap-1.5">
                {outrosLotes.map((l) => {
                  const sl = statusStyles(getStatus(l).level);
                  return (
                    <button key={l.id} onClick={() => onTrocarLote && onTrocarLote(l)} style={{ background: T.card }} className="w-full text-left rounded-xl p-2.5 flex items-center justify-between gap-2">
                      <div className="min-w-0">
                        <div className="flex items-center gap-1.5">
                          <span style={{ background: sl.bg, color: sl.fg }} className="text-[9px] font-bold px-1.5 py-0.5 rounded">{sl.label}</span>
                          <span className="text-xs font-semibold">{formatarData(l.validade)}</span>
                          <span style={{ color: T.subtext }} className="text-[10px]">· {l.quantidade || 1}{l.porPeso ? "kg" : "un"}</span>
                        </div>
                        {gerarCodigoLocalizacao(l) && <p style={{ color: T.subtext }} className="text-[10px] mt-0.5 font-mono">{gerarCodigoLocalizacao(l)}</p>}
                      </div>
                      <ChevronRight size={14} color={T.subtext} className="shrink-0" />
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* Trilha imutável: histórico de alterações de validade deste código — não pode ser apagado, nem por aqui */}
          {historicoValidade && historicoValidade.length > 0 && (
            <div style={{ background: "#FFF8E8", borderColor: "#F0DDA6" }} className="rounded-2xl mt-3.5 p-3 border">
              <button onClick={() => setMostrarHistoricoValidade((v) => !v)} className="w-full flex items-center justify-between">
                <p style={{ color: "#8A6414" }} className="text-[10px] font-bold uppercase tracking-wide flex items-center gap-1.5">
                  <ShieldCheck size={12} /> Validade já foi alterada {historicoValidade.length}x
                </p>
                <ChevronRight size={14} color="#8A6414" className={`shrink-0 transition-transform ${mostrarHistoricoValidade ? "rotate-90" : ""}`} />
              </button>
              {mostrarHistoricoValidade && (
                <div className="flex flex-col gap-2 mt-2.5">
                  {historicoValidade.map((h) => (
                    <div key={h.id} style={{ background: "rgba(255,255,255,0.6)" }} className="rounded-xl p-2.5">
                      <p style={{ color: "#8A6414" }} className="text-xs font-semibold">
                        {formatarData(h.validadeAnterior)} → {formatarData(h.validadeNova)}
                      </p>
                      <p style={{ color: "#8A6414" }} className="text-[10px] mt-0.5 opacity-80">
                        {h.alteradoPor || "—"} · {formatarDataHoraExtenso(h.alteradoEm)}
                      </p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

        </div>
        <div style={{ borderColor: T.border, background: T.card }} className="shrink-0 max-h-[55%] overflow-y-auto px-4 pt-3 pb-[calc(1rem+env(safe-area-inset-bottom))] border-t">
          <motion.button whileTap={{ scale: 0.98 }} onClick={() => setConfirmandoBaixa(true)}
            style={{ background: `linear-gradient(135deg, ${RED} 0%, ${RED_DARK} 100%)` }}
            className="w-full py-3.5 rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-red-900/20">
            <PackageX className="w-5 h-5 text-white" />
            <span className="text-white font-bold text-sm">Registrar ação</span>
          </motion.button>

          <div className="flex items-center justify-around mt-3.5">
            {onEdit && (
              <button onClick={() => onEdit(item)} className="flex flex-col items-center gap-1.5">
                <div style={{ background: T.chipBg }} className="h-11 w-11 rounded-2xl flex items-center justify-center"><Edit2 size={16} style={{ color: T.text }} /></div>
                <span style={{ color: T.subtext }} className="text-[10px] font-medium">Editar</span>
              </button>
            )}
            {onDuplicate && (
              <button onClick={() => onDuplicate(item)} className="flex flex-col items-center gap-1.5">
                <div style={{ background: T.chipBg }} className="h-11 w-11 rounded-2xl flex items-center justify-center"><Layers size={16} style={{ color: T.text }} /></div>
                <span style={{ color: T.subtext }} className="text-[10px] font-medium">Novo lote</span>
              </button>
            )}
            <button onClick={() => onShare(item)} className="flex flex-col items-center gap-1.5">
              <div style={{ background: T.chipBg }} className="h-11 w-11 rounded-2xl flex items-center justify-center"><Share2 size={16} style={{ color: T.text }} /></div>
              <span style={{ color: T.subtext }} className="text-[10px] font-medium">Compartilhar</span>
            </button>
            <button onClick={() => setConfirmandoExclusao(true)} className="flex flex-col items-center gap-1.5">
              <div style={{ background: RED_SOFT }} className="h-11 w-11 rounded-2xl flex items-center justify-center"><Trash2 size={16} color={RED_DARK} /></div>
              <span style={{ color: RED_DARK }} className="text-[10px] font-medium">Excluir</span>
            </button>
          </div>

          {confirmandoExclusao && (
            <div style={{ background: RED_SOFT }} className="mt-2.5 rounded-xl p-2.5">
              <p style={{ color: RED_DARK }} className="text-[11px] font-medium text-center mb-2">Excluir sem registrar no histórico. Qual o motivo?</p>
              <div className="grid grid-cols-2 gap-1.5">
                {MOTIVOS_EXCLUSAO.map((m) => (
                  <button key={m} onClick={() => setMotivoExclusao(m)}
                    style={motivoExclusao === m ? { background: RED_DARK, color: "#fff" } : { background: "#fff", color: RED_DARK }}
                    className="text-[11px] font-medium py-2 rounded-xl border" >
                    {m}
                  </button>
                ))}
              </div>
              {motivoExclusao === "Outro" && (
                <input value={motivoExclusaoOutro} onChange={(e) => setMotivoExclusaoOutro(e.target.value.slice(0, 80))}
                  placeholder="Descreva o motivo..." autoFocus
                  style={{ background: "#fff", color: RED_DARK, borderColor: RED_DARK }}
                  className="w-full min-w-0 mt-2 border rounded-xl px-3 py-2 text-xs outline-none" />
              )}
              <div className="flex gap-2 mt-2.5">
                <button onClick={() => { setConfirmandoExclusao(false); setMotivoExclusao(null); setMotivoExclusaoOutro(""); }} style={{ color: T.subtext }} className="flex-1 text-[11px] py-1.5">Cancelar</button>
                <button
                  onClick={() => onExcluir(item, motivoExclusao === "Outro" ? (motivoExclusaoOutro.trim() || "Outro") : motivoExclusao)}
                  disabled={!motivoExclusao || (motivoExclusao === "Outro" && !motivoExclusaoOutro.trim())}
                  style={{ background: RED_DARK, color: "#fff" }} className="flex-1 text-[11px] font-semibold py-1.5 rounded-xl disabled:opacity-40">
                  Sim, excluir
                </button>
              </div>
            </div>
          )}
        </div>
      </motion.div>
    </div>

    {confirmandoBaixa && (
      <div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center">
        <div onClick={() => { setConfirmandoBaixa(false); setSubEtapa(null); }} className="absolute inset-0 bg-black/60" />
        <div style={{ background: T.card }} className="relative w-full max-w-md lg:max-w-lg lg:ring-1 lg:ring-black/10 lg:shadow-2xl rounded-t-[28px] p-5 pb-[calc(1.75rem+env(safe-area-inset-bottom))] max-h-[90dvh] overflow-y-auto sm:rounded-2xl">
          <div className="flex items-center gap-2.5 mb-4">
            <div style={{ background: RED_SOFT }} className="h-10 w-10 rounded-2xl flex items-center justify-center shrink-0"><PackageX size={18} color={RED_DARK} /></div>
            <div className="min-w-0">
              <h3 className="font-bold text-sm">Dar baixa</h3>
              <p style={{ color: T.subtext }} className="text-xs truncate">{item.nome}</p>
            </div>
          </div>

          {subEtapa === null && (
            <>
              <p style={{ color: T.subtext }} className="text-[11px] font-medium mb-2">O que foi feito com o produto?</p>
              <div className="grid grid-cols-2 gap-2">
                {MOTIVOS_BAIXA.map((m) => (
                  <button key={m} onClick={() => escolherMotivo(m)} style={{ background: T.chipBg, color: T.text }} className="text-xs font-medium py-3 rounded-xl">{m}</button>
                ))}
              </div>
              <button onClick={() => setConfirmandoBaixa(false)} style={{ color: T.subtext }} className="w-full text-xs py-2.5 mt-2">Cancelar</button>
            </>
          )}

          {subEtapa === "promocao" && (
            <>
              <p style={{ color: T.subtext }} className="text-[11px] font-medium mb-1.5">Qual o preço promocional? O produto continua sendo monitorado.</p>
              <input type="number" inputMode="decimal" min="0" step="0.01" autoFocus value={precoPromoInput} onChange={(e) => setPrecoPromoInput(e.target.value)}
                placeholder="0,00" style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-3 text-sm outline-none focus:ring-2" />
              <div className="flex gap-2 mt-3">
                <button onClick={() => setSubEtapa(null)} style={{ color: T.subtext }} className="flex-1 text-xs py-2.5">Voltar</button>
                <button onClick={() => { onAplicarPromocao(item, clampNumero(precoPromoInput, 0, 999999)); setConfirmandoBaixa(false); setSubEtapa(null); }}
                  disabled={!precoPromoInput} style={{ background: BLUE, color: "#fff" }} className="flex-[2] text-sm font-semibold py-2.5 rounded-xl">
                  Aplicar promoção
                </button>
              </div>
            </>
          )}

          {subEtapa === "quantidade" && (
            <>
              <p className="text-[11px] font-medium mb-1.5">
                Quantas {item.porPeso ? "kg" : "unidade(s)"} de <b>{motivoPendente === "Vencido" || (motivoPendente || "").toLowerCase().includes("venc") ? "vencido" : "baixa"}</b> vão ser dadas?
              </p>
              <p style={{ color: T.subtext }} className="text-[10px] mb-1.5">A quantidade que venceu pode ser diferente da que foi cadastrada/vendida — confira antes de confirmar.</p>
              <input type="number" inputMode="decimal" min={item.porPeso ? 0.001 : 1} step={item.porPeso ? "0.001" : "1"} max={item.quantidade || 99999} autoFocus value={quantidadeFinalInput}
                onChange={(e) => setQuantidadeFinalInput(item.porPeso ? e.target.value.replace(/[^\d.]/g, "") : e.target.value.replace(/[^\d]/g, ""))}
                style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-3 text-sm outline-none focus:ring-2" />
              <p style={{ color: T.subtext }} className="text-[10px] mt-1">de {item.quantidade}{item.porPeso ? "kg" : " unidade(s)"} cadastrada(s)</p>
              <div className="flex gap-2 mt-3">
                <button onClick={() => setSubEtapa(null)} style={{ color: T.subtext }} className="flex-1 text-xs py-2.5">Voltar</button>
                <button onClick={() => onBaixa(item, motivoPendente, item.porPeso ? clampNumero(quantidadeFinalInput, 0.001, item.quantidade || 9999) : clampNumero(quantidadeFinalInput, 1, item.quantidade || 99999))}
                  disabled={!quantidadeFinalInput || Number(quantidadeFinalInput) <= 0}
                  style={{ background: RED_DARK, color: "#fff" }} className="flex-[2] text-sm font-semibold py-2.5 rounded-xl disabled:opacity-40">
                  Confirmar baixa
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    )}
    </>
  );
}

// ============ Prioridade Inteligente ("PRIORIDADE DE PERDA") ============
// Aba dedicada: não ordena por data de validade — ordena pelo risco real de perda
// (urgência + valor + quantidade + política de troca + reincidência). Um produto que
// vence depois mas não tem troca com o fornecedor pode furar a frente de um que vence
// antes mas tem troca garantida — é exatamente essa a diferença do motor calcularPrioridade.
// ============ Prioridade / Histórico / Auditoria — versões dashboard (PC) ============
function PrioridadeDashboard({ T, prioridades, valorEmRisco, urgenteCount, semTrocaCount, filtro, setFiltro, filtrados, onOpenDetail }) {
  const fmt = useFormatarMoedaComCamada();
  const porSetor = {};
  prioridades.forEach((x) => { porSetor[x.item.setor] = (porSetor[x.item.setor] || 0) + x.p.valor; });
  const top = Object.entries(porSetor).sort((a, b) => b[1] - a[1]).slice(0, 7).map(([label, value]) => ({ label, value, color: RED, right: fmt(value) }));
  const cols = [
    { key: "pos", label: "#", width: 44, render: (x) => <span style={{ color: T.subtext }} className="tabular-nums">{filtrados.indexOf(x) + 1}</span> },
    { key: "nome", label: "Produto", render: (x) => <div className="flex items-center gap-3"><Thumb foto={x.item.foto} size={34} /><div><p className="font-semibold truncate max-w-[20rem]">{x.item.nome}</p><p style={{ color: T.subtext }} className="text-[11px]">{x.item.setor}{gerarCodigoLocalizacao(x.item) ? ` · ${gerarCodigoLocalizacao(x.item)}` : ""}</p></div></div> },
    { key: "nivel", label: "Nível", render: (x) => <DashBadge bg={x.p.nivel === "urgente" ? RED_DARK : RED_SOFT} color={x.p.nivel === "urgente" ? "#fff" : RED_DARK}>{x.p.nivel === "urgente" ? "URGENTE" : "ATENÇÃO"}</DashBadge> },
    { key: "score", label: "Risco", render: (x) => <div className="flex items-center gap-2 w-28"><div style={{ background: T.chipBg }} className="h-1.5 flex-1 rounded-full overflow-hidden"><div style={{ width: `${x.p.score}%`, background: x.p.score > 70 ? RED_DARK : "#E0921C" }} className="h-full" /></div><span className="text-xs font-bold tabular-nums">{x.p.score}</span></div> },
    { key: "prazo", label: "Prazo", render: (x) => <span className="text-xs">{x.p.status.level === "expired" ? `vencido há ${Math.abs(x.p.dias)}d` : x.p.dias === 0 ? "vence hoje" : `em ${x.p.dias}d`}</span> },
    { key: "troca", label: "Troca", render: (x) => x.p.semTroca ? <DashBadge bg="#4A1013" color="#FFD5D8">SEM TROCA</DashBadge> : <span style={{ color: T.subtext }} className="text-xs">—</span> },
    { key: "valor", label: "Valor", align: "right", render: (x) => <span className="font-semibold tabular-nums">{fmt(x.p.valor)}</span> },
    { key: "acao", label: "Ação recomendada", render: (x) => <span style={{ color: BLUE_DARK }} className="text-xs font-semibold">{x.p.acao}</span> },
  ];
  return (
    <div className="hidden lg:block">
      <DashPageHeader T={T} title="Prioridade de perda" subtitle="Ordenado por quem gera a maior perda e tem menor chance de recuperação" />
      <div className="grid grid-cols-2 xl:grid-cols-4 gap-4 mb-5">
        <DashKpi T={T} label="Valor priorizado em risco" value={fmt(valorEmRisco)} sub="soma dos itens em risco" Icon={TrendingDown} accent={RED_DARK} />
        <DashKpi T={T} label="Em risco" value={prioridades.length} sub="vencidos + em alerta" Icon={AlertTriangle} accent={RED} />
        <DashKpi T={T} label="Urgentes" value={urgenteCount} sub="agir primeiro" Icon={Flame} accent={RED_DARK} />
        <DashKpi T={T} label="Sem troca" value={semTrocaCount} sub="não voltam ao fornecedor" Icon={ShieldAlert} accent="#C98A0C" />
      </div>
      {prioridades.length === 0 ? (
        <DashCard T={T} title="Nenhum produto em risco agora"><p style={{ color: T.subtext }} className="text-sm">Assim que algo entrar em alerta ou vencer, a prioridade aparece aqui.</p></DashCard>
      ) : (
        <div className="grid grid-cols-4 gap-4 items-start">
          <DashCard T={T} title="Valor em risco por setor" className="col-span-1"><DashHBars T={T} data={top} /></DashCard>
          <DashCard T={T} title="Fila de prioridade" subtitle={`${filtrados.length} produto(s) — clique para abrir`} className="col-span-3"
            right={<DashTabs T={T} value={filtro} onChange={setFiltro} options={[{ id: "todos", label: `Todos (${prioridades.length})` }, { id: "urgente", label: `Urgente (${urgenteCount})`, color: RED_DARK }, { id: "sem_troca", label: `Sem troca (${semTrocaCount})` }]} />}>
            <DashTable T={T} cols={cols} rows={filtrados.map((x) => ({ ...x, id: x.item.id }))} onRow={(x) => onOpenDetail(x.item)} empty="Nenhum produto nesse filtro." />
          </DashCard>
        </div>
      )}
    </div>
  );
}

function HistoricoDashboard({ T, filtrado, periodo, setPeriodo, valorPerdido, valorTotalMovimentado, rankingSetores, rankingResponsaveis, reincidentes, exportarCSV, exportarPlanilha }) {
  const fmt = useFormatarMoedaComCamada();
  const dias = Math.min(periodo, 30);
  const serie = Array.from({ length: dias }, (_, k) => { const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - (dias - 1 - k)); return d; });
  const dadosSerie = serie.map((d) => ({ label: `${String(d.getDate()).padStart(2, "0")}/${String(d.getMonth() + 1).padStart(2, "0")}`,
    value: Math.round(filtrado.filter((h) => new Date(h.dataBaixa).toDateString() === d.toDateString()).reduce((a, h) => a + (Number(h.quantidade) || 1) * (Number(h.precoUnitario) || 0), 0)) }));
  const cols = [
    { key: "nome", label: "Produto", render: (h) => <div><p className="font-semibold truncate max-w-[22rem]">{h.nome}</p>{h.barcode && <p style={{ color: T.subtext }} className="text-[10.5px] font-mono">{h.barcode}</p>}</div> },
    { key: "setor", label: "Setor", render: (h) => <span style={{ color: T.subtext }}>{h.setor}</span> },
    { key: "data", label: "Baixa", render: (h) => <span className="text-xs tabular-nums">{formatarDataHora(h.dataBaixa)}</span> },
    { key: "motivo", label: "Ação", render: (h) => <DashBadge bg={h.vencidoAntes ? RED_SOFT : BLUE_SOFT} color={h.vencidoAntes ? RED_DARK : BLUE_DARK}>{h.motivo}</DashBadge> },
    { key: "qtd", label: "Qtd", align: "right", render: (h) => <span className="tabular-nums">{h.quantidade || 1}</span> },
    { key: "valor", label: "Valor", align: "right", render: (h) => <span className="font-semibold tabular-nums">{fmt((Number(h.quantidade) || 1) * (Number(h.precoUnitario) || 0))}</span> },
    { key: "por", label: "Responsável", render: (h) => <span style={{ color: T.subtext }} className="text-xs">{h.registradoPor || "—"}</span> },
  ];
  const btn = { background: T.card, borderColor: T.border, color: T.text };
  return (
    <div className="hidden lg:block">
      <DashPageHeader T={T} title="Histórico de baixas" subtitle={`Últimos ${periodo} dias · ${filtrado.length} baixa(s)`}
        right={<>
          <DashTabs T={T} value={periodo} onChange={setPeriodo} options={[{ id: 7, label: "7 dias" }, { id: 30, label: "30 dias" }, { id: 90, label: "90 dias" }]} />
          <button onClick={exportarCSV} style={btn} className="text-xs font-semibold px-3 py-2 rounded-xl border flex items-center gap-1.5"><Download size={13} /> CSV</button>
          <button onClick={() => exportarPlanilha("xlsx")} style={btn} className="text-xs font-semibold px-3 py-2 rounded-xl border flex items-center gap-1.5"><FileSpreadsheet size={13} /> Excel</button>
        </>} />
      <div className="grid grid-cols-2 xl:grid-cols-4 gap-4 mb-5">
        <DashKpi T={T} label="Perda por vencimento" value={fmt(valorPerdido)} sub="baixas de produto vencido" Icon={TrendingDown} accent={RED_DARK} />
        <DashKpi T={T} label="Valor movimentado" value={fmt(valorTotalMovimentado)} sub="todas as baixas" Icon={Boxes} accent={BLUE} />
        <DashKpi T={T} label="Baixas registradas" value={filtrado.length} sub={`nos últimos ${periodo} dias`} Icon={History} accent="#1F9D55" />
        <DashKpi T={T} label="Reincidentes" value={reincidentes.length} sub="produtos com 3+ perdas" Icon={AlertTriangle} accent="#C98A0C" />
      </div>
      <div className="grid grid-cols-3 gap-4 mb-5">
        <DashCard T={T} title="Valor baixado por dia" subtitle={`Últimos ${dias} dias`} className="col-span-2"><DashArea T={T} data={dadosSerie} color={RED_DARK} gid="hist" /></DashCard>
        <DashCard T={T} title="Perda por setor" subtitle="% do valor no período">
          {rankingSetores.length ? <DashHBars T={T} data={rankingSetores.map((r) => ({ label: r.setor, value: r.valor, color: RED, right: `${Math.round(r.pct)}% · ${fmt(r.valor)}` }))} /> : <p style={{ color: T.subtext }} className="text-sm py-8 text-center">Sem baixas.</p>}
        </DashCard>
      </div>
      <div className="grid grid-cols-3 gap-4">
        <div className="col-span-2">
          <DashCard T={T} title="Baixas registradas" subtitle="Mais recentes primeiro">
            <DashTable T={T} cols={cols} rows={[...filtrado].sort((a, b) => new Date(b.dataBaixa) - new Date(a.dataBaixa)).slice(0, 100).map((h, i) => ({ ...h, id: h.id ?? i }))} empty="Nenhuma baixa no período." />
          </DashCard>
        </div>
        <div className="flex flex-col gap-4">
          <DashCard T={T} title="Quem registra" subtitle="Ranking de responsáveis">
            {rankingResponsaveis.length ? <DashHBars T={T} data={rankingResponsaveis.map(([n, c]) => ({ label: n, value: c, color: BLUE, right: `${c}` }))} /> : <p style={{ color: T.subtext }} className="text-sm py-4 text-center">—</p>}
          </DashCard>
          <DashCard T={T} title="Reincidentes" subtitle="3+ perdas em 60 dias">
            {reincidentes.length ? <DashHBars T={T} data={reincidentes.map((r) => ({ label: r.nome, value: r.datas.length, color: RED_DARK, right: `${r.datas.length}x` }))} /> : <p style={{ color: T.subtext }} className="text-sm py-4 text-center">Nenhum reincidente.</p>}
          </DashCard>
        </div>
      </div>
    </div>
  );
}

function AuditoriaDashboard({ T, auditoria, filtrada, busca, setBusca }) {
  const hojeStr = new Date().toDateString();
  const hoje = auditoria.filter((a) => new Date(a.criadoEm).toDateString() === hojeStr).length;
  const porUser = {};
  auditoria.forEach((a) => { const u = a.usuario || "Alguém"; porUser[u] = (porUser[u] || 0) + 1; });
  const topUsers = Object.entries(porUser).sort((a, b) => b[1] - a[1]).slice(0, 6);
  const dias = Array.from({ length: 14 }, (_, k) => { const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - (13 - k)); return d; });
  const serie = dias.map((d) => ({ label: `${String(d.getDate()).padStart(2, "0")}/${String(d.getMonth() + 1).padStart(2, "0")}`, value: auditoria.filter((a) => new Date(a.criadoEm).toDateString() === d.toDateString()).length }));
  const cols = [
    { key: "quando", label: "Quando", width: 190, render: (a) => <span className="text-xs tabular-nums">{formatarDataHoraExtenso(a.criadoEm)}</span> },
    { key: "usuario", label: "Pessoa", render: (a) => <span className="font-semibold">{a.usuario || "Alguém"}</span> },
    { key: "acao", label: "Ação", render: (a) => <span>{a.acao}</span> },
    { key: "detalhe", label: "Detalhe", render: (a) => <span style={{ color: T.subtext }} className="text-xs">{a.detalhe || "—"}</span> },
  ];
  return (
    <div className="hidden lg:block">
      <DashPageHeader T={T} title="Auditoria" subtitle="Trilha de tudo o que foi feito no app" />
      <div className="grid grid-cols-2 xl:grid-cols-4 gap-4 mb-5">
        <DashKpi T={T} label="Ações registradas" value={auditoria.length} sub="total" Icon={DocumentMagnifyingGlassIcon} accent={BLUE} />
        <DashKpi T={T} label="Ações hoje" value={hoje} sub="desde 00:00" Icon={ClockIcon} accent="#1F9D55" />
        <DashKpi T={T} label="Pessoas ativas" value={Object.keys(porUser).length} sub="com ao menos 1 ação" Icon={Boxes} accent={RED} />
        <DashKpi T={T} label="Mais ativa" value={topUsers[0] ? topUsers[0][0].split(" ")[0] : "—"} sub={topUsers[0] ? `${topUsers[0][1]} ação(ões)` : ""} Icon={ShieldCheck} accent="#C98A0C" />
      </div>
      <div className="grid grid-cols-3 gap-4 mb-5">
        <DashCard T={T} title="Atividade nos últimos 14 dias" className="col-span-2"><DashArea T={T} data={serie} color={BLUE} gid="aud" /></DashCard>
        <DashCard T={T} title="Ações por pessoa">{topUsers.length ? <DashHBars T={T} data={topUsers.map(([n, c]) => ({ label: n, value: c, color: BLUE, right: `${c}` }))} /> : <p style={{ color: T.subtext }} className="text-sm py-8 text-center">Sem registros.</p>}</DashCard>
      </div>
      <DashCard T={T} title="Registros" subtitle={`${filtrada.length} ação(ões)`}
        right={<div style={{ background: T.inputBg, borderColor: T.inputBorder }} className="flex items-center gap-2 border rounded-xl px-3 py-1.5 w-72"><MagnifyingGlassIcon className="w-4 h-4" style={{ color: T.subtext }} /><input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar pessoa, ação, detalhe…" style={{ color: T.text }} className="bg-transparent outline-none text-sm flex-1" /></div>}>
        <DashTable T={T} cols={cols} rows={filtrada.slice(0, 150).map((a, i) => ({ ...a, id: a.id ?? i }))} empty="Nenhum registro encontrado." />
      </DashCard>
    </div>
  );
}

function PrioridadeInteligenteView({ T, items, historico, onOpenDetail }) {
  const podeVerValores = useValoresVisiveis();
  const [filtro, setFiltro] = useState("todos"); // todos | urgente | sem_troca

  const prioridadesTodas = useMemo(() => {
    return items
      .map((it) => ({ item: it, p: calcularPrioridade(it, historico) }))
      .filter((x) => x.p && (x.p.status.level === "alert" || x.p.status.level === "expired"))
      .sort((a, b) => b.p.score - a.p.score);
  }, [items, historico]);

  const valorEmRisco = prioridadesTodas.reduce((acc, x) => acc + x.p.valor, 0);
  const semTrocaCount = prioridadesTodas.filter((x) => x.p.semTroca).length;
  const urgenteCount = prioridadesTodas.filter((x) => x.p.nivel === "urgente").length;

  const porSetor = {};
  prioridadesTodas.forEach((x) => { porSetor[x.item.setor] = (porSetor[x.item.setor] || 0) + 1; });
  const topSetores = Object.entries(porSetor).sort((a, b) => b[1] - a[1]).slice(0, 4);

  const filtrados = prioridadesTodas.filter((x) => {
    if (filtro === "urgente") return x.p.nivel === "urgente";
    if (filtro === "sem_troca") return x.p.semTroca;
    return true;
  });

  return (
    <>
    <PrioridadeDashboard T={T} prioridades={prioridadesTodas} valorEmRisco={valorEmRisco} urgenteCount={urgenteCount} semTrocaCount={semTrocaCount} filtro={filtro} setFiltro={setFiltro} filtrados={filtrados} onOpenDetail={onOpenDetail} />
    <div className="px-4 pt-4 pb-6 lg:hidden">
      <PalcoPagina className="mb-4" titulo="Prioridade de perda" subtitulo="Quem gera mais perda vem primeiro">
        <ValorPalco rotulo="Valor priorizado em risco" valor={podeVerValores ? formatarMoeda(valorEmRisco) : "•••"} />
        <PilulasPalco itens={[["Em risco", prioridadesTodas.length, "#F5A524"], ["Urgentes", urgenteCount, "#E31E24"], ["Sem troca", semTrocaCount, "#9AA3B2"]]} />
        <p className="text-[11.5px] text-white/75 mt-3 leading-snug">Cruza validade, quantidade, valor e política de troca com o fornecedor — não é só “vence primeiro”.</p>
      </PalcoPagina>

      {prioridadesTodas.length === 0 ? (
        <EstadoVazioNovo T={T} Icone={ShieldCheck} titulo="Nenhum produto em risco agora" texto="Assim que algo entrar em alerta ou vencer, a prioridade aparece aqui." />
      ) : (
        <>
          <FaixaChips T={T} valor={filtro} onChange={setFiltro} opcoes={[["todos", "Todos", prioridadesTodas.length], ["urgente", "Urgentes", urgenteCount], ["sem_troca", "Sem troca", semTrocaCount]]} />
          {filtrados.length === 0 && <p style={{ color: T.subtext }} className="text-sm text-center py-8">Nenhum produto nesse filtro.</p>}
          <div className="flex flex-col gap-3">
            {filtrados.map(({ item, p }, i) => {
              const urgente = p.nivel === "urgente";
              const cor = urgente ? "#E31E24" : "#E0921C";
              return (
                <motion.button key={item.id} initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} transition={{ type: "spring", stiffness: 320, damping: 26, delay: Math.min(i * 0.04, 0.3) }}
                  whileTap={{ scale: 0.98 }} onClick={() => onOpenDetail(item)} style={{ background: T.card, boxShadow: urgente ? "0 0 0 2px rgba(227,30,36,.35), 0 10px 24px -12px rgba(0,0,0,.2)" : undefined }}
                  className="rounded-[24px] shadow-lg shadow-black/5 text-left w-full p-3.5">
                  <div className="flex items-start gap-3">
                    <span style={{ background: urgente ? "#E31E24" : RED_SOFT, color: urgente ? "#fff" : RED_DARK }} className="h-9 w-9 rounded-full text-[13px] font-extrabold flex items-center justify-center shrink-0">{i + 1}</span>
                    <div className="min-w-0 flex-1">
                      <p style={{ color: T.text }} className="font-extrabold text-[14.5px] leading-tight">{item.nome}</p>
                      <p style={{ color: T.subtext }} className="text-[11.5px] mt-0.5">{item.setor}{gerarCodigoLocalizacao(item) ? ` · ${gerarCodigoLocalizacao(item)}` : ""}</p>
                    </div>
                    <span style={{ background: urgente ? RED_SOFT : "#FCF0DD", color: cor }} className="text-[10.5px] font-extrabold rounded-full px-2.5 py-1 shrink-0 flex items-center gap-1">{urgente && <Flame size={10} />}{urgente ? "URGENTE" : "ATENÇÃO"}</span>
                  </div>
                  <p style={{ color: T.text }} className="text-[12px] font-semibold mt-2.5">
                    {item.quantidade || 1} un · {p.status.level === "expired" ? `vencido há ${Math.abs(p.dias)}d` : p.dias === 0 ? "vence hoje" : `vence em ${p.dias}d`}{p.valor > 0 && podeVerValores ? ` · ${formatarMoeda(p.valor)}` : ""}
                  </p>
                  <div className="flex items-center gap-2 mt-2">
                    <div style={{ background: T.chipBg }} className="flex-1 h-2 rounded-full overflow-hidden"><div style={{ width: `${p.score}%`, background: cor }} className="h-full rounded-full" /></div>
                    <span style={{ color: T.subtext }} className="text-[10.5px] font-bold tabular-nums">risco {p.score}/100</span>
                  </div>
                  {(p.semTroca || p.reincidencias >= 3) && (
                    <div className="flex gap-1.5 mt-2.5 flex-wrap">
                      {p.semTroca && <span style={{ background: "#4A1013", color: "#FFD5D8" }} className="text-[10px] font-bold px-2 py-1 rounded-full flex items-center gap-1"><ShieldAlert size={10} /> Sem troca</span>}
                      {p.reincidencias >= 3 && <span style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-[10px] font-bold px-2 py-1 rounded-full flex items-center gap-1"><Repeat size={10} /> Reincidente</span>}
                    </div>
                  )}
                  <div style={{ background: T.chipBg }} className="rounded-2xl px-3 py-2 mt-2.5"><p style={{ color: T.text }} className="text-[11.5px] font-bold"><span style={{ color: T.subtext }} className="font-bold">AÇÃO · </span>{p.acao}</p></div>
                </motion.button>
              );
            })}
          </div>
        </>
      )}
    </div>
  </>
  );
}

