// ============ Scan (câmera com leitor nativo + ZXing de reforço) ============
function ScanView({ T, onDetected, onCancel, variante, ocupado }) {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const detectorRef = useRef(null);
  const zxingControlsRef = useRef(null);
  const rafRef = useRef(null);
  const [status, setStatus] = useState("iniciando");
  const [erroMsg, setErroMsg] = useState("");
  const [manualMode, setManualMode] = useState(false);
  const [manualCode, setManualCode] = useState("");
  const [facing, setFacing] = useState("environment");
  const [torchOn, setTorchOn] = useState(false);
  const [torchDisponivel, setTorchDisponivel] = useState(false);
  const tentativasRef = useRef(0);

  // Leitura em múltiplos ângulos: o código pode estar na vertical (etiqueta virada, embalagem
  // cilíndrica etc). A cada tentativa giramos o frame pra um ângulo diferente (0°/90°/270°/180°),
  // assim o leitor consegue achar o código nos dois modos sem precisar que o usuário gire o produto.
  const ANGULOS_TENTATIVA = [0, 90, 270, 180];
  const rotationCanvasRef = useRef(null);
  const obterFonteRotacionada = useCallback((video, angulo) => {
    if (angulo === 0) return video;
    if (!rotationCanvasRef.current) rotationCanvasRef.current = document.createElement("canvas");
    const canvas = rotationCanvasRef.current;
    const w = video.videoWidth, h = video.videoHeight;
    if (!w || !h) return video;
    if (angulo === 90 || angulo === 270) { canvas.width = h; canvas.height = w; } else { canvas.width = w; canvas.height = h; }
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    ctx.save();
    ctx.translate(canvas.width / 2, canvas.height / 2);
    ctx.rotate((angulo * Math.PI) / 180);
    ctx.drawImage(video, -w / 2, -h / 2, w, h);
    ctx.restore();
    return canvas;
  }, []);

  const pararTudo = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    if (zxingControlsRef.current) { try { zxingControlsRef.current.stop(); } catch {} zxingControlsRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach((t) => t.stop()); streamRef.current = null; }
  }, []);

  // Correção do bug do iPhone: antes, cada frame tentava só 1 ângulo do ciclo [0,90,270,180],
  // então o ângulo 0° (leitura normal, sem rotação) só era testado 1 a cada 4 frames — na prática
  // isso "diluiu" a leitura normal em 75% e, somado ao custo de rotacionar o canvas a cada frame,
  // o app parava de bipar até código na posição de sempre. Agora TODO frame tenta o ângulo 0°
  // primeiro (rápido, sem canvas) e só usa 1 ângulo extra do ciclo como tentativa secundária.
  const scanLoopNativo = useCallback(() => {
    rafRef.current = requestAnimationFrame(async () => {
      if (videoRef.current && detectorRef.current && videoRef.current.readyState >= 2) {
        try {
          const codes = await detectorRef.current.detect(videoRef.current);
          if (codes && codes.length > 0) { pararTudo(); onDetected(codes[0].rawValue); return; }
        } catch (e) {
          // erro pontual de detecção num frame — segue tentando
        }
        tentativasRef.current += 1;
        if (tentativasRef.current % 3 === 0) {
          const angulo = ANGULOS_TENTATIVA[(tentativasRef.current / 3) % ANGULOS_TENTATIVA.length];
          if (angulo !== 0) {
            try {
              const fonte = obterFonteRotacionada(videoRef.current, angulo);
              const codes = await detectorRef.current.detect(fonte);
              if (codes && codes.length > 0) { pararTudo(); onDetected(codes[0].rawValue); return; }
            } catch (e) {
              // idem — segue tentando
            }
          }
        }
      }
      scanLoopNativo();
    });
  }, [onDetected, pararTudo, obterFonteRotacionada]);

  // Leitor alternativo (Safari/iOS, que não tem BarcodeDetector nativo): em vez de depender do método
  // "contínuo" da própria lib (que tem se mostrado instável no Safari), controlamos o loop nós mesmos —
  // desenhamos cada frame do vídeo num canvas e pedimos pra biblioteca decodificar só aquele frame.
  // É o mesmo padrão usado acima pro leitor nativo, então o comportamento fica consistente e mais fácil de confiar.
  // Correção: a build do ZXing carregada pelo CDN não tem o método "decodeFromCanvas" (é isso que
  // aparecia como erro no diagnóstico do iPhone). O método público e confirmado nessa versão é
  // "decode(elemento)", que aceita o próprio <video> direto — ele mesmo cuida do canvas interno.
  const canvasZXingRef = useRef(null);
  const scanLoopZXing = useCallback((codeReader) => {
    function decodeUmFrame(video, angulo) {
      const fonte = obterFonteRotacionada(video, angulo);
      if (typeof codeReader.decode === "function") return codeReader.decode(fonte);
      // fallback pra builds antigas que só tenham decodeFromCanvas
      if (!canvasZXingRef.current) canvasZXingRef.current = document.createElement("canvas");
      const canvas = canvasZXingRef.current;
      const largura = fonte.videoWidth || fonte.width, altura = fonte.videoHeight || fonte.height;
      canvas.width = largura;
      canvas.height = altura;
      canvas.getContext("2d", { willReadFrequently: true }).drawImage(fonte, 0, 0, largura, altura);
      return codeReader.decodeFromCanvas(canvas);
    }
    // Mesma correção do leitor nativo: no Safari/iPhone (que cai nesse caminho, sem BarcodeDetector),
    // o ciclo de ângulos fazia o app só tentar a leitura "normal" (0°) 1 a cada 4 frames, e cada
    // rotação de canvas tem custo alto de CPU no iOS — juntos, isso derrubava a taxa de leitura a
    // ponto de nunca bipar. Agora todo frame tenta 0° primeiro (direto no vídeo, sem canvas) e só
    // testa um ângulo rotacionado a cada 3 frames, como reforço pra código na vertical/de lado.
    function tentarFrame() {
      const video = videoRef.current;
      if (video && video.readyState >= 2 && video.videoWidth > 0) {
        try {
          const resultado = decodeUmFrame(video, 0);
          if (resultado) { pararTudo(); onDetected(resultado.getText()); return; }
        } catch (e) {
          // "não encontrou código neste frame" é esperado na maioria das tentativas — segue tentando
        }
        tentativasRef.current += 1;
        if (tentativasRef.current % 3 === 0) {
          const angulo = ANGULOS_TENTATIVA[(tentativasRef.current / 3) % ANGULOS_TENTATIVA.length];
          if (angulo !== 0) {
            try {
              const resultado = decodeUmFrame(video, angulo);
              if (resultado) { pararTudo(); onDetected(resultado.getText()); return; }
            } catch (e) {
              // idem — segue tentando
            }
          }
        }
      }
      rafRef.current = requestAnimationFrame(tentarFrame);
    }
    tentarFrame();
  }, [onDetected, pararTudo, obterFonteRotacionada]);

  function carregarZXing() {
    return new Promise((resolve, reject) => {
      if (window.ZXing) { resolve(window.ZXing); return; }
      const script = document.createElement("script");
      script.src = ZXING_CDN;
      script.async = true;
      script.onload = () => resolve(window.ZXing);
      script.onerror = () => reject(new Error("zxing-load-fail"));
      document.head.appendChild(script);
    });
  }
  function comTimeout(promessa, ms) {
    return Promise.race([
      promessa,
      new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), ms))
    ]);
  }

  const iniciarCamera = useCallback(async (facingAtual) => {
    setStatus("iniciando");
    setErroMsg("");
    pararTudo();
    tentativasRef.current = 0;

    // trava de segurança: se nada resolver em 12s (comum em Safari/iOS com script lento), cai pro modo manual
    const timeoutGeral = setTimeout(() => {
      setStatus((atual) => {
        if (atual === "iniciando") { setManualMode(true); setErroMsg("A câmera demorou demais para responder neste navegador."); return "erro"; }
        return atual;
      });
    }, 12000);

    // tenta a câmera preferida (frontal/traseira) com resolução ideal; se o navegador recusar
    // a restrição exata, tenta de novo de forma mais permissiva antes de desistir
    async function obterStream() {
      try {
        return await navigator.mediaDevices.getUserMedia({
          video: { facingMode: { ideal: facingAtual }, width: { ideal: 720 }, height: { ideal: 1280 } }
        });
      } catch {
        return await navigator.mediaDevices.getUserMedia({ video: true });
      }
    }

    try {
      const stream = await obterStream();
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play().catch(() => {}); // iOS pode rejeitar a promise mesmo funcionando; não bloqueia o fluxo
      }

      let capabilities = {};
      try { const track = stream.getVideoTracks()[0]; capabilities = track && track.getCapabilities ? track.getCapabilities() : {}; } catch {}
      setTorchDisponivel(!!capabilities.torch);
      setTorchOn(false);

      if ("BarcodeDetector" in window) {
        detectorRef.current = new window.BarcodeDetector({ formats: ["ean_13", "ean_8", "upc_a", "upc_e", "code_128", "code_39", "itf"] });
        clearTimeout(timeoutGeral);
        setStatus("ok");
        scanLoopNativo();
        return;
      }

      // navegador sem leitor nativo (ex: Safari/iOS): carrega leitor alternativo dinamicamente
      try {
        const ZXing = await comTimeout(carregarZXing(), 8000);
        const hints = new Map();
        // restringe aos formatos de código de barras de varejo (mais rápido e mais preciso que testar tudo, incl. QR)
        hints.set(ZXing.DecodeHintType.POSSIBLE_FORMATS, [
          ZXing.BarcodeFormat.EAN_13, ZXing.BarcodeFormat.EAN_8, ZXing.BarcodeFormat.UPC_A,
          ZXing.BarcodeFormat.UPC_E, ZXing.BarcodeFormat.CODE_128, ZXing.BarcodeFormat.CODE_39,
          ZXing.BarcodeFormat.ITF
        ]);
        hints.set(ZXing.DecodeHintType.TRY_HARDER, true);
        const codeReader = new ZXing.BrowserMultiFormatReader(hints);
        clearTimeout(timeoutGeral);
        setStatus("ok");
        // espera 1 frame real de vídeo chegar antes de começar a tentar ler (evita ler tela preta no início)
        requestAnimationFrame(() => scanLoopZXing(codeReader));
      } catch (e) {
        clearTimeout(timeoutGeral);
        setStatus("sem-suporte");
        setManualMode(true);
      }
    } catch (e) {
      clearTimeout(timeoutGeral);
      if (e && e.name === "NotAllowedError") setErroMsg("Permissão de câmera negada. Habilite o acesso nas configurações do navegador.");
      else if (e && e.name === "NotFoundError") setErroMsg("Nenhuma câmera foi encontrada neste dispositivo.");
      else setErroMsg("Não foi possível acessar a câmera.");
      setStatus("erro");
      setManualMode(true);
    }
  }, [onDetected, pararTudo, scanLoopNativo, scanLoopZXing]);

  // Único ponto que liga/desliga a câmera: roda de novo sempre que voltamos do modo manual
  // (botão "voltar pra câmera" ou "tentar novamente") ou quando a câmera frontal/traseira é trocada.
  // Isso corrige o bug de tentar reiniciar a câmera antes do <video> existir na tela.
  useEffect(() => {
    if (!manualMode) iniciarCamera(facing);
    return () => pararTudo();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [facing, manualMode]);

  function alternarTorch() {
    const track = streamRef.current && streamRef.current.getVideoTracks()[0];
    if (!track) return;
    const novoEstado = !torchOn;
    track.applyConstraints({ advanced: [{ torch: novoEstado }] }).then(() => setTorchOn(novoEstado)).catch(() => {});
  }

  function submitManual() {
    const code = apenasNumeros(manualCode, 14);
    if (code.length < 4) return;
    pararTudo();
    onDetected(code);
  }

  // Crachá (cadastro/vínculo): tela cheia própria, mesma leitura de código por baixo.
  if (variante === "cracha") {
    return (
      <TelaBiparCracha status={status} erroMsg={erroMsg} videoRef={videoRef} manualMode={manualMode} setManualMode={setManualMode}
        manualCode={manualCode} setManualCode={setManualCode} torchDisponivel={torchDisponivel} torchOn={torchOn} onTorch={alternarTorch}
        onTrocarCamera={() => setFacing((f) => (f === "environment" ? "user" : "environment"))} onConfirmarManual={submitManual}
        onVoltar={() => { pararTudo(); onCancel(); }} onTentarDeNovo={() => { setErroMsg(""); setManualMode(false); }} ocupado={ocupado} />
    );
  }

  return (
    <div className="px-4 pt-4">
      {!manualMode && (
        <div className="relative rounded-[28px] overflow-hidden bg-black" style={{ aspectRatio: "3/4" }}>
          <video ref={videoRef} className="w-full h-full object-cover" muted autoPlay playsInline webkit-playsinline="true" />
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <div className="w-[78%] h-40 relative">
              <CornerGuide pos="tl" />
              <CornerGuide pos="tr" />
              <CornerGuide pos="bl" />
              <CornerGuide pos="br" />
              <div style={{ background: RED }} className="absolute left-0 right-0 top-1/2 h-0.5 animate-pulse" />
              <div style={{ background: RED }} className="absolute top-0 bottom-0 left-1/2 w-0.5 animate-pulse opacity-70" />
            </div>
          </div>

          <div className="absolute top-3 right-3 flex flex-col gap-2">
            {torchDisponivel && (
              <button onClick={alternarTorch} className="h-9 w-9 rounded-full bg-black/50 flex items-center justify-center">
                {torchOn ? <Flashlight size={16} color="#FFD34D" /> : <FlashlightOff size={16} color="#fff" />}
              </button>
            )}
            <button onClick={() => setFacing((f) => (f === "environment" ? "user" : "environment"))} className="h-9 w-9 rounded-full bg-black/50 flex items-center justify-center">
              <SwitchCamera size={16} color="#fff" />
            </button>
          </div>

          {status === "iniciando" && (
            <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center gap-2">
              <Loader2 className="animate-spin" color="#fff" size={26} />
              <p className="text-white text-xs">Abrindo câmera...</p>
            </div>
          )}
          <div className="absolute bottom-3 left-0 right-0 text-center">
            <p className="text-white/90 text-xs font-medium bg-black/40 inline-block px-3 py-1 rounded-full">Aponte para o código — na horizontal ou na vertical</p>
          </div>
        </div>
      )}

      {status === "erro" && (
        <div style={{ background: RED_SOFT }} className="mt-3 rounded-xl px-3 py-2.5 flex items-start gap-2">
          <AlertTriangle size={14} color={RED_DARK} className="mt-0.5 shrink-0" />
          <div className="flex-1">
            <p className="text-xs font-medium" style={{ color: RED_DARK }}>{erroMsg}</p>
            <button onClick={() => { setManualMode(false); }} className="text-xs font-semibold mt-1.5 flex items-center gap-1" style={{ color: RED_DARK }}>
              <RotateCcw size={12} /> Tentar novamente
            </button>
          </div>
        </div>
      )}
      {status === "sem-suporte" && (
        <div className="mt-3">
          <p style={{ color: T.subtext }} className="text-xs text-center">Este navegador não suporta leitura automática. Digite manualmente.</p>
          <button onClick={() => setManualMode(false)} className="w-full text-xs font-semibold mt-1.5 flex items-center justify-center gap-1" style={{ color: BLUE }}>
            <RotateCcw size={12} /> Tentar carregar a câmera de novo
          </button>
        </div>
      )}

      {!manualMode ? (
        <button onClick={() => setManualMode(true)} className="w-full mt-4 flex items-center justify-center gap-2 text-sm font-medium py-3 rounded-2xl border" style={{ borderColor: BLUE, color: BLUE }}>
          Digitar código manualmente
        </button>
      ) : (
        <div style={{ background: T.card, borderColor: T.border }} className="mt-4 rounded-2xl p-4 border shadow-lg shadow-black/5">
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Código do produto (somente números)</label>
          <input autoFocus inputMode="numeric" pattern="[0-9]*" maxLength={14} value={manualCode}
            onChange={(e) => setManualCode(apenasNumeros(e.target.value, 14))}
            onKeyDown={(e) => { if (e.key === "Enter") submitManual(); }} placeholder="Ex: 7891234567890"
            style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full font-mono border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2" />
          <p style={{ color: T.subtext }} className="text-[10px] mt-1">{manualCode.length}/14 dígitos {manualCode.length > 0 && manualCode.length < 4 ? "— mínimo 4 dígitos" : ""}</p>
          <button onClick={submitManual} disabled={manualCode.length < 4} style={{ background: manualCode.length >= 4 ? BLUE : "#C7CEDA" }} className="w-full mt-2 text-white text-sm font-semibold py-2.5 rounded-xl">
            Confirmar código
          </button>
          {status !== "erro" && status !== "sem-suporte" && (
            <button onClick={() => setManualMode(false)} style={{ color: T.subtext }} className="w-full mt-2 text-xs py-1">Voltar para a câmera</button>
          )}
        </div>
      )}

      <button onClick={() => { pararTudo(); onCancel(); }} style={{ color: T.subtext }} className="w-full mt-3 text-xs py-2">Cancelar</button>
    </div>
  );
}

function CornerGuide({ pos }) {
  const estilosPorCanto = {
    tl: "top-0 left-0 border-t-[3px] border-l-[3px] rounded-tl-md",
    tr: "top-0 right-0 border-t-[3px] border-r-[3px] rounded-tr-md",
    bl: "bottom-0 left-0 border-b-[3px] border-l-[3px] rounded-bl-md",
    br: "bottom-0 right-0 border-b-[3px] border-r-[3px] rounded-br-md",
  };
  return <div className={`absolute h-5 w-5 ${estilosPorCanto[pos]}`} style={{ borderColor: RED }} />;
}

// ============ Confirmar produto ============
function ConfirmProductView({ T, barcode, initial, wasKnown, nomesExistentes, onCancel, onContinue, onSalvarSemValidade, onSalvarEdicaoDireto, intencaoFluxo, setoresExtra, subsetoresExtra, onCriarSetor, onCriarSubsetor }) {
  const [nome, setNome] = useState(initial.nome || "");
  const [sugestoesAbertas, setSugestoesAbertas] = useState(false);
  const sugestoesFiltradas = useMemo(() => {
    const alvo = nome.trim().toLowerCase();
    if (alvo.length < 2) return [];
    return (nomesExistentes || []).filter((n) => n.toLowerCase().includes(alvo) && n.toLowerCase() !== alvo).slice(0, 6);
  }, [nome, nomesExistentes]);
  const [setor, setSetor] = useState(initial.setor || "");
  const [setorCustom, setSetorCustom] = useState("");
  const [subsetor, setSubsetor] = useState(initial.subsetor || "");
  const [criandoSetor, setCriandoSetor] = useState(false);
  const [novoSetorNome, setNovoSetorNome] = useState("");
  const [novoSetorPerecivel, setNovoSetorPerecivel] = useState(false);
  const [criandoSubsetor, setCriandoSubsetor] = useState(false);
  const [novoSubsetorNome, setNovoSubsetorNome] = useState("");
  const [foto, setFoto] = useState(initial.foto || null);
  const [buscando, setBuscando] = useState(!wasKnown);
  const [origem, setOrigem] = useState(wasKnown ? "catalogo" : null);
  const [carregandoFoto, setCarregandoFoto] = useState(false);
  const [carregandoIA, setCarregandoIA] = useState(false);
  const [erroIA, setErroIA] = useState(false);
  const [corredor, setCorredor] = useState(initial.corredor || "");
  const [ladoCorredor, setLadoCorredor] = useState(initial.ladoCorredor || "");
  const [modulo, setModulo] = useState(initial.modulo || "");
  const [prateleira, setPrateleira] = useState(initial.prateleira || "");
  const [categoriaGiro, setCategoriaGiro] = useState(initial.categoriaGiro || "");
  const [politicaTroca, setPoliticaTroca] = useState(initial.politicaTroca || "");
  const [precoUnitario, setPrecoUnitario] = useState(initial.precoUnitario != null ? String(initial.precoUnitario) : "");
  const [porPeso, setPorPeso] = useState(!!initial.porPeso);
  const [tamanho, setTamanho] = useState(initial.tamanho || "");
  const [unidadeMedida, setUnidadeMedida] = useState(initial.unidadeMedida || unidadeSugeridaPeloSetor(initial.setor));
  const [cadastrarEstoque, setCadastrarEstoque] = useState(!!initial.cadastrarEstoque);
  const [corredorDeposito, setCorredorDeposito] = useState(initial.corredorDeposito || "");
  const [moduloDeposito, setModuloDeposito] = useState(initial.moduloDeposito || "");
  const [nivelDeposito, setNivelDeposito] = useState(initial.nivelDeposito || "");
  const [vaoDeposito, setVaoDeposito] = useState(initial.vaoDeposito || "");
  const cameraInputRef = useRef(null);
  const galeriaInputRef = useRef(null);

  useEffect(() => {
    if (wasKnown) { setBuscando(false); return; }
    let cancelled = false;
    (async () => {
      const resultado = await buscarProdutoPorCodigo(barcode);
      if (!cancelled) {
        if (resultado) {
          setNome(formatarNomeProfissional(resultado.nome));
          setOrigem("api");
          if (resultado.foto) {
            setFoto((atual) => atual || resultado.foto);
          } else {
            // A API de busca achou o nome mas não achou foto — pede uma sugestão pro Gemini
            // (edge function, com busca no Google) em vez de deixar o produto sem imagem.
            buscarFotoComIA(resultado.nome);
          }
        }
        setBuscando(false);
      }
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [barcode, wasKnown]);

  async function buscarFotoComIA(nomeProduto) {
    try {
      const { data, error } = await supabase.functions.invoke("identificar-produto", { body: { nomeProduto, apenasFoto: true } });
      if (error) throw error;
      if (data && data.foto) setFoto((atual) => atual || data.foto);
    } catch (e) {
      console.warn("Sugestão de foto pela IA falhou:", e);
    }
  }

  async function handleFotoSelecionada(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setCarregandoFoto(true);
    try { setFoto(await compressImage(file)); } catch {}
    setCarregandoFoto(false);
    e.target.value = "";
  }

  // Lista de modelos a tentar em ordem — o Google aposenta modelos do Gemini com frequência (o
  // gemini-2.0-flash usado antes foi desativado). Se o primeiro da lista não existir mais (erro 404),
  // tenta automaticamente o próximo, então uma futura aposentadoria não derruba a função de novo.
  // IMPORTANTE: "pro" é o modelo mais lento da família (feito pra raciocínio complexo) — pra uma
  // tarefa simples de identificar produto numa foto, "flash" já resolve muito mais rápido com
  // qualidade equivalente. Por isso ele vai por último, só como último recurso.
  const GEMINI_MODELOS = ["gemini-2.5-flash-lite", "gemini-2.5-flash", "gemini-flash-latest", "gemini-2.5-pro"];
  const TIMEOUT_POR_MODELO_MS = 8000;

  async function chamarGemini(apiKey, base64) {
    let ultimoErro = null;
    for (const modelo of GEMINI_MODELOS) {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), TIMEOUT_POR_MODELO_MS);
      try {
        const resp = await fetch(
          `https://generativelanguage.googleapis.com/v1beta/models/${modelo}:generateContent?key=${apiKey}`,
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            signal: controller.signal,
            body: JSON.stringify({
              contents: [{
                parts: [
                  {
                    text: `Identifique o produto de supermercado nesta foto (nome comercial completo, com marca se visível). ` +
                      `Escolha o setor mais adequado dentre exatamente estas opções: ${SETORES.join(", ")}. ` +
                      `Responda SOMENTE com um JSON válido, sem markdown, no formato exato: {"nome": "...", "setor": "..."}`
                  },
                  { inline_data: { mime_type: "image/jpeg", data: base64 } }
                ]
              }]
            })
          }
        );
        clearTimeout(timeoutId);
        if (resp.status === 404) { ultimoErro = new Error(`modelo ${modelo} indisponível`); continue; }
        const data = await resp.json();
        if (data.error) { ultimoErro = new Error(data.error.message || "erro na API do Gemini"); continue; }
        const texto = data?.candidates?.[0]?.content?.parts?.[0]?.text || "{}";
        const limpo = texto.replace(/```json|```/g, "").trim();
        const resultado = JSON.parse(limpo);
        if (!resultado.nome) { ultimoErro = new Error("resposta sem nome"); continue; }
        return resultado;
      } catch (e) {
        clearTimeout(timeoutId);
        ultimoErro = e.name === "AbortError" ? new Error(`modelo ${modelo} demorou mais de ${TIMEOUT_POR_MODELO_MS / 1000}s`) : e;
      }
    }
    throw ultimoErro || new Error("Gemini indisponível");
  }

  async function identificarComIA() {
    if (!foto) return;
    setCarregandoIA(true);
    setErroIA(false);
    const base64 = foto.split(",")[1];
    const erros = [];

    // Caminho preferido: Edge Function "identificar-produto" (roda no servidor, não expõe
    // chave de API no navegador). Se ela falhar por qualquer motivo, cai pro Gemini direto do
    // cliente como reforço, pra não deixar a função inteira fora do ar.
    try {
      const { data, error } = await supabase.functions.invoke("identificar-produto", { body: { imagemBase64: base64 } });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      if (data && data.nome) {
        setNome(formatarNomeProfissional(data.nome));
        if (data.setor && SETORES.includes(data.setor)) setSetor(data.setor);
        setOrigem("ia");
        setCarregandoIA(false);
        return;
      }
      throw new Error("resposta sem nome");
    } catch (e) {
      erros.push(`Edge Function: ${e?.message || e}`);
      console.warn("Edge Function identificar-produto falhou, tentando Gemini direto:", e);
    }

    try {
      const apiKey = import.meta.env.VITE_GEMINI_API_KEY;
      if (!apiKey) throw new Error("VITE_GEMINI_API_KEY não configurada no app");
      const resultado = await chamarGemini(apiKey, base64);
      setNome(formatarNomeProfissional(resultado.nome));
      if (resultado.setor && SETORES.includes(resultado.setor)) setSetor(resultado.setor);
      setOrigem("ia");
    } catch (e) {
      erros.push(`Gemini direto: ${e?.message || e}`);
      console.error("Falha ao identificar com IA:", erros.join(" | "));
      setErroIA(erros.join(" | "));
    }
    setCarregandoIA(false);
  }

  const setorFinal = setor === "Outro" ? setorCustom.trim() : setor;
  const podeContinuar = nome.trim().length > 0 && setorFinal.length > 0 && (setorFinal !== "Mercearia" || !!subsetor) && Number(precoUnitario) > 0;

  // Cadastro em etapas (tipo tela de pagamento): uma coisa de cada vez, menos chance de errar
  // com o coletor numa mão e o produto na outra. Cada etapa só libera "Avançar" com o essencial dela ok.
  const [etapa, setEtapa] = useState(1);
  const TOTAL_ETAPAS = 4;
  const NOMES_ETAPA = ["Produto", "Preço", "Setor", "Detalhes"];
  const podeAvancarEtapa = {
    1: nome.trim().length > 0,
    2: Number(precoUnitario) > 0,
    3: setorFinal.length > 0 && (setorFinal !== "Mercearia" || !!subsetor),
    4: true,
  }[etapa];

  return (
    <div className="px-4 pt-4">
      <div className="flex items-center gap-1.5 mb-4">
        {Array.from({ length: TOTAL_ETAPAS }).map((_, i) => (
          <div key={i} style={{ background: i + 1 <= etapa ? BLUE : T.chipBg }} className="h-1.5 flex-1 rounded-full transition-colors" />
        ))}
      </div>
      <p style={{ color: T.subtext }} className="text-[11px] font-semibold uppercase tracking-wide mb-3">
        Etapa {etapa} de {TOTAL_ETAPAS} · {NOMES_ETAPA[etapa - 1]}
      </p>

      <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl p-4 border shadow-lg shadow-black/5 mb-4">
        <div style={{ color: T.subtext }} className="flex items-center gap-2 text-xs mb-1"><Barcode size={13} /> Código escaneado</div>
        <p className="font-mono font-semibold text-base">{barcode}</p>
      </div>

      {etapa === 1 && buscando && (
        <div style={{ color: T.subtext }} className="flex items-center gap-2 text-xs mb-4 px-1">
          <Loader2 size={14} className="animate-spin" color={BLUE} /> Buscando nome do produto em português...
        </div>
      )}
      {etapa === 1 && !buscando && origem === "catalogo" && (
        <div style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-xs font-medium px-3 py-2 rounded-xl mb-4 flex items-center gap-1.5">
          <Check size={13} /> Produto já cadastrado — dados preenchidos automaticamente.
        </div>
      )}
      {etapa === 1 && !buscando && origem === "api" && (
        <div style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-xs font-medium px-3 py-2 rounded-xl mb-4 flex items-center gap-1.5">
          <Check size={13} /> Nome localizado automaticamente. Confira antes de continuar.
        </div>
      )}
      {etapa === 1 && !buscando && origem === "ia" && (
        <div style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-xs font-medium px-3 py-2 rounded-xl mb-4 flex items-center gap-1.5">
          <Sparkles size={13} /> Identificado pela IA (Gemini) a partir da foto. Confira antes de continuar.
        </div>
      )}
      {etapa === 1 && !buscando && !origem && (
        <div style={{ background: RED_SOFT, color: RED_DARK }} className="text-xs font-medium px-3 py-2 rounded-xl mb-4 flex items-center gap-1.5">
          <AlertTriangle size={13} /> Produto não encontrado. Preencha os dados manualmente.
        </div>
      )}

      <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl p-4 border shadow-lg shadow-black/5 flex flex-col gap-4">
        {etapa === 1 && (<>
        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Foto do produto</label>
          <div className="flex items-center gap-3">
            {foto ? <img src={foto} alt="" className="h-16 w-16 rounded-xl object-cover" /> : (
              <div style={{ background: T.chipBg }} className="h-16 w-16 rounded-xl flex items-center justify-center"><ImageOff size={20} color={T.subtext} /></div>
            )}
            <div className="flex flex-col gap-1.5 flex-1">
              <div className="flex gap-1.5">
                <button onClick={() => cameraInputRef.current && cameraInputRef.current.click()} disabled={carregandoFoto}
                  style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="flex-1 text-xs font-medium py-2 rounded-xl flex items-center justify-center gap-1.5">
                  {carregandoFoto ? <Loader2 size={13} className="animate-spin" /> : <Camera size={13} />} Tirar foto
                </button>
                <button onClick={() => galeriaInputRef.current && galeriaInputRef.current.click()} disabled={carregandoFoto}
                  style={{ background: T.chipBg, color: T.text }} className="flex-1 text-xs font-medium py-2 rounded-xl flex items-center justify-center gap-1.5">
                  <Images size={13} /> Galeria
                </button>
              </div>
              {foto && <button onClick={() => setFoto(null)} style={{ color: RED_DARK }} className="text-[11px] font-medium text-left">Remover foto</button>}
            </div>
            <input ref={cameraInputRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={handleFotoSelecionada} />
            <input ref={galeriaInputRef} type="file" accept="image/*" className="hidden" onChange={handleFotoSelecionada} />
          </div>
          {foto && (
            <button onClick={identificarComIA} disabled={carregandoIA}
              style={{ background: `linear-gradient(135deg, ${BLUE} 0%, ${BLUE_DARK} 100%)` }}
              className="w-full mt-2.5 text-white text-xs font-semibold py-2.5 rounded-xl flex items-center justify-center gap-1.5">
              {carregandoIA ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} />}
              {carregandoIA ? "Identificando com IA..." : "Identificar produto com IA (Gemini)"}
            </button>
          )}
          {erroIA && (
            <div style={{ background: RED_SOFT }} className="mt-1.5 rounded-lg p-2">
              <p style={{ color: RED_DARK }} className="text-[11px]">Não consegui identificar o produto. Tente uma foto mais nítida, ou preencha manualmente.</p>
              <p style={{ color: RED_DARK }} className="text-[9px] mt-1 font-mono opacity-70 break-all">{erroIA}</p>
            </div>
          )}
        </div>

        <div className="relative">
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Nome do produto</label>
          <input value={nome} maxLength={120}
            onChange={(e) => { setNome(sanitizarTexto(e.target.value, 120)); setSugestoesAbertas(true); }}
            onFocus={() => setSugestoesAbertas(true)} onBlur={() => setTimeout(() => setSugestoesAbertas(false), 150)}
            placeholder="Ex: Leite integral 1L"
            style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2" />
          <p style={{ color: T.subtext }} className="text-[10px] mt-1">Pode escrever normal — ao salvar, vira o padrão abreviado do sistema (ex: "BISC. CHOC/AVELÃ").</p>
          {sugestoesAbertas && nome.trim().length >= 2 && sugestoesFiltradas.length > 0 && (
            <div style={{ background: T.card, borderColor: T.border }} className="absolute z-20 left-0 right-0 mt-1 border rounded-xl shadow-lg shadow-black/10 overflow-hidden max-h-48 overflow-y-auto">
              {sugestoesFiltradas.map((s) => (
                <button key={s} onMouseDown={() => { setNome(s); setSugestoesAbertas(false); }}
                  style={{ borderColor: T.border }} className="w-full text-left px-3 py-2.5 text-xs border-b last:border-b-0" >
                  {s}
                </button>
              ))}
            </div>
          )}
        </div>
        </>)}
        {etapa === 2 && (
        <div>
          {ehPerecivel(setorFinal) && (
            <div className="flex items-center justify-between mb-1.5">
              <label style={{ color: T.subtext }} className="text-xs font-semibold block">Este produto é vendido por peso?</label>
              <div className="flex rounded-lg overflow-hidden shrink-0" style={{ border: `1px solid ${T.inputBorder}` }}>
                <button type="button" onClick={() => setPorPeso(true)}
                  style={porPeso ? { background: BLUE, color: "#fff" } : { background: T.inputBg, color: T.subtext }}
                  className="text-[10.5px] font-semibold px-2.5 py-1.5">Peso (KG)</button>
                <button type="button" onClick={() => setPorPeso(false)}
                  style={!porPeso ? { background: BLUE, color: "#fff" } : { background: T.inputBg, color: T.subtext }}
                  className="text-[10.5px] font-semibold px-2.5 py-1.5">Unidade</button>
              </div>
            </div>
          )}
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">{porPeso ? "Preço Unitário/KG (R$)" : "Valor unitário (R$)"} <span style={{ color: RED }}>*</span></label>
          <input type="number" inputMode="decimal" min="0.01" step="0.01" value={precoUnitario}
            onChange={(e) => setPrecoUnitario(e.target.value)} placeholder="0,00"
            style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2" />
          {!(Number(precoUnitario) > 0) && <p style={{ color: T.subtext }} className="text-[10px] mt-1">Obrigatório pra calcular o valor em risco do produto.</p>}
          {porPeso && <p style={{ color: T.subtext }} className="text-[10px] mt-1">Ao lançar a validade, o valor total é calculado automaticamente pelo peso pesado.</p>}
        </div>
        )}
        {etapa === 2 && (
        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Tamanho / quantidade da embalagem</label>
          <div className="flex gap-2">
            <input value={tamanho} inputMode="decimal" maxLength={7}
              onChange={(e) => setTamanho(e.target.value.replace(/[^\d.,]/g, "").slice(0, 7))}
              placeholder="Ex: 500, 1, 900"
              style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="flex-1 min-w-0 border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2" />
            <select value={unidadeMedida} onChange={(e) => setUnidadeMedida(e.target.value)}
              style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }}
              className="w-[84px] shrink-0 border rounded-xl px-2 py-2.5 text-sm font-semibold outline-none focus:ring-2">
              {ordemUnidadesPeloSetor(setorFinal).map((u) => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>
          <p style={{ color: T.subtext }} className="text-[10px] mt-1">Fica salvo no cadastro — não precisa digitar de novo ao lançar a validade.</p>
        </div>
        )}
        {etapa === 3 && (
        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Setor <span style={{ color: RED }}>*</span></label>
          {!criandoSetor ? (
            <>
              <select value={setor} onChange={(e) => {
                if (e.target.value === "___novo___") { setCriandoSetor(true); return; }
                setSetor(e.target.value); setSubsetor("");
              }}
                style={{ background: T.inputBg, color: T.text, borderColor: T.border }}
                className="w-full border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2">
                <option value="">Selecione o setor...</option>
                {SETORES.filter((s) => s !== "Outro").map((s) => <option key={s} value={s}>{s}</option>)}
                {setoresExtra.map((s) => <option key={s.nome} value={s.nome}>{s.nome} (customizado)</option>)}
                <option value="___novo___">+ Criar novo setor...</option>
                <option value="Outro">Outro (não salvar)</option>
              </select>
              {setor === "Outro" && (
                <input value={setorCustom} maxLength={40} onChange={(e) => setSetorCustom(sanitizarTexto(e.target.value, 40))} placeholder="Digite o setor"
                  style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full mt-2 border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2" />
              )}
            </>
          ) : (
            <div style={{ background: T.chipBg }} className="rounded-xl p-3">
              <p style={{ color: T.subtext }} className="text-[10px] font-medium mb-1.5">Nome do novo setor</p>
              <input autoFocus value={novoSetorNome} maxLength={40} onChange={(e) => setNovoSetorNome(sanitizarTexto(e.target.value, 40))} placeholder="Ex: Padaria Fina"
                style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2 mb-2" />
              <button onClick={() => setNovoSetorPerecivel((v) => !v)} className="flex items-center gap-2 mb-3">
                <div style={{ background: novoSetorPerecivel ? BLUE : T.inputBg, borderColor: T.border }} className="h-5 w-5 rounded border flex items-center justify-center">
                  {novoSetorPerecivel && <Check size={12} color="#fff" />}
                </div>
                <span className="text-xs">É um setor de produtos perecíveis?</span>
              </button>
              <div className="flex gap-2">
                <button onClick={() => { setCriandoSetor(false); setNovoSetorNome(""); }} style={{ color: T.subtext }} className="flex-1 text-xs py-2">Cancelar</button>
                <button onClick={() => {
                  if (!novoSetorNome.trim()) return;
                  onCriarSetor(novoSetorNome, novoSetorPerecivel);
                  setSetor(novoSetorNome.trim()); setSubsetor("");
                  setCriandoSetor(false); setNovoSetorNome(""); setNovoSetorPerecivel(false);
                }} disabled={!novoSetorNome.trim()} style={{ background: BLUE, color: "#fff" }} className="flex-[2] text-xs font-semibold py-2 rounded-xl">
                  Criar e usar
                </button>
              </div>
            </div>
          )}

          {setor && setor !== "Outro" && !criandoSetor && (
            <div className="mt-2">
              <div className="flex items-center justify-between mb-1">
                <label style={{ color: T.subtext }} className="text-[10px] font-medium block">
                  Subsetor {setor === "Mercearia" && <span style={{ color: RED }}>*</span>}
                </label>
                {!criandoSubsetor && (
                  <button onClick={() => setCriandoSubsetor(true)} style={{ color: BLUE }} className="text-[10px] font-semibold">+ Novo subsetor</button>
                )}
              </div>
              {criandoSubsetor ? (
                <div className="flex gap-1.5">
                  <input autoFocus value={novoSubsetorNome} maxLength={40} onChange={(e) => setNovoSubsetorNome(sanitizarTexto(e.target.value, 40))} placeholder="Nome do subsetor"
                    style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="flex-1 border rounded-xl px-3 py-2 text-sm outline-none focus:ring-2" />
                  <button onClick={() => {
                    if (!novoSubsetorNome.trim()) return;
                    onCriarSubsetor(setor, novoSubsetorNome);
                    setSubsetor(novoSubsetorNome.trim());
                    setCriandoSubsetor(false); setNovoSubsetorNome("");
                  }} style={{ background: BLUE, color: "#fff" }} className="text-xs font-semibold px-3 rounded-xl shrink-0">Criar</button>
                  <button onClick={() => { setCriandoSubsetor(false); setNovoSubsetorNome(""); }} style={{ color: T.subtext }} className="text-xs px-2 shrink-0">✕</button>
                </div>
              ) : (
                (() => {
                  const opcoes = [...(setor === "Mercearia" ? SUBSETORES_MERCEARIA : []), ...subsetoresExtra.filter((s) => s.setor === setor).map((s) => s.nome)];
                  return opcoes.length > 0 ? (
                    <div className="grid grid-cols-2 gap-1.5">
                      {opcoes.map((s) => (
                        <button key={s} onClick={() => setSubsetor(s)}
                          style={subsetor === s ? { background: BLUE, color: "#fff" } : { background: T.chipBg, color: T.text }}
                          className="text-[11px] font-medium py-2 rounded-xl">
                          {s}
                        </button>
                      ))}
                    </div>
                  ) : (
                    <p style={{ color: T.subtext }} className="text-[10px]">Nenhum subsetor ainda pra {setor}. Toque em "+ Novo subsetor" pra criar.</p>
                  );
                })()
              )}
            </div>
          )}
        </div>
        )}

        {etapa === 4 && (
        <div style={{ borderColor: T.border }} className="pt-1 border-t">
          <div className="mt-3" />
          <label style={{ color: T.subtext }} className="text-[10px] font-medium mb-1 block">Categoria de giro</label>
          <div className="flex gap-1.5 mb-3">
            {CATEGORIAS_GIRO.map((g) => (
              <button key={g} onClick={() => setCategoriaGiro(categoriaGiro === g ? "" : g)}
                style={categoriaGiro === g ? { background: BLUE, color: "#fff" } : { background: T.chipBg, color: T.text }}
                className="flex-1 text-[11px] font-medium py-1.5 rounded-xl">
                {g}
              </button>
            ))}
          </div>

          <label style={{ color: T.subtext }} className="text-[10px] font-medium mb-1 block">Política de troca com o fornecedor</label>
          <div className="flex gap-1.5">
            {POLITICAS_TROCA.map((p) => (
              <button key={p.valor} onClick={() => setPoliticaTroca(politicaTroca === p.valor ? "" : p.valor)}
                style={politicaTroca === p.valor ? (p.valor === "sem_troca" ? { background: RED, color: "#fff" } : { background: "#1F9D55", color: "#fff" }) : { background: T.chipBg, color: T.text }}
                className="flex-1 text-[11px] font-semibold py-2 rounded-xl">
                {p.label}
              </button>
            ))}
          </div>
          {politicaTroca && <p style={{ color: T.subtext }} className="text-[10px] mt-1.5">{POLITICAS_TROCA.find((p) => p.valor === politicaTroca)?.desc}</p>}
        </div>
        )}
      </div>

      <div className="flex gap-2 mt-5">
        <button onClick={etapa === 1 ? onCancel : () => setEtapa((e) => e - 1)} style={{ color: T.subtext, borderColor: T.border }} className="flex-1 text-sm font-medium py-3 rounded-2xl border">
          {etapa === 1 ? "Cancelar" : "Voltar"}
        </button>
        {etapa < TOTAL_ETAPAS ? (
          <button disabled={!podeAvancarEtapa} onClick={() => setEtapa((e) => e + 1)}
            style={{ background: podeAvancarEtapa ? BLUE : "#C7CEDA" }} className="flex-[2] text-sm font-semibold py-3 rounded-2xl text-white flex items-center justify-center gap-1.5">
            Continuar <ChevronRight size={16} />
          </button>
        ) : intencaoFluxo === "cadastro" ? (
          <button disabled={!podeContinuar} onClick={() => onSalvarSemValidade({
            nome: formatarNomeProfissional(nome.trim()), setor: setorFinal, subsetor: subsetor || null, foto, corredor: corredor || null, ladoCorredor: ladoCorredor || null,
            modulo: modulo || null, prateleira: prateleira || null, categoriaGiro: categoriaGiro || null, politicaTroca: politicaTroca || null, precoUnitario: Number(precoUnitario) || 0, porPeso, tamanho: tamanho || null, unidadeMedida, cadastrarEstoque, corredorDeposito: cadastrarEstoque ? (corredorDeposito || null) : null, moduloDeposito: cadastrarEstoque ? (moduloDeposito || null) : null, nivelDeposito: cadastrarEstoque ? (nivelDeposito || null) : null, vaoDeposito: cadastrarEstoque ? (vaoDeposito || null) : null
          })}
            style={{ background: podeContinuar ? BLUE : "#C7CEDA" }} className="flex-[2] text-sm font-semibold py-3 rounded-2xl text-white flex items-center justify-center gap-1.5">
            <Check size={16} /> Salvar cadastro
          </button>
        ) : onSalvarEdicaoDireto ? (
          <button disabled={!podeContinuar} onClick={() => onSalvarEdicaoDireto({
            nome: formatarNomeProfissional(nome.trim()), setor: setorFinal, subsetor: subsetor || null, foto, corredor: corredor || null, ladoCorredor: ladoCorredor || null,
            modulo: modulo || null, prateleira: prateleira || null, categoriaGiro: categoriaGiro || null, politicaTroca: politicaTroca || null, precoUnitario: Number(precoUnitario) || 0, porPeso, tamanho: tamanho || null, unidadeMedida, cadastrarEstoque, corredorDeposito: cadastrarEstoque ? (corredorDeposito || null) : null, moduloDeposito: cadastrarEstoque ? (moduloDeposito || null) : null, nivelDeposito: cadastrarEstoque ? (nivelDeposito || null) : null, vaoDeposito: cadastrarEstoque ? (vaoDeposito || null) : null
          })}
            style={{ background: podeContinuar ? BLUE : "#C7CEDA" }} className="flex-[2] text-sm font-semibold py-3 rounded-2xl text-white flex items-center justify-center gap-1.5">
            <Check size={16} /> Salvar alterações
          </button>
        ) : (
          <button disabled={!podeContinuar} onClick={() => onContinue({
            nome: formatarNomeProfissional(nome.trim()), setor: setorFinal, subsetor: subsetor || null, foto, corredor: corredor || null, ladoCorredor: ladoCorredor || null,
            modulo: modulo || null, prateleira: prateleira || null, categoriaGiro: categoriaGiro || null, politicaTroca: politicaTroca || null, precoUnitario: Number(precoUnitario) || 0, porPeso, tamanho: tamanho || null, unidadeMedida, cadastrarEstoque, corredorDeposito: cadastrarEstoque ? (corredorDeposito || null) : null, moduloDeposito: cadastrarEstoque ? (moduloDeposito || null) : null, nivelDeposito: cadastrarEstoque ? (nivelDeposito || null) : null, vaoDeposito: cadastrarEstoque ? (vaoDeposito || null) : null
          })}
            style={{ background: podeContinuar ? RED : "#E9CBCC" }} className="flex-[2] text-sm font-semibold py-3 rounded-2xl text-white flex items-center justify-center gap-1.5">
            Avançar <ChevronRight size={16} />
          </button>
        )}
      </div>
      {etapa === TOTAL_ETAPAS && intencaoFluxo === "validade" && onSalvarEdicaoDireto && (
        <button disabled={!podeContinuar} onClick={() => onContinue({
          nome: formatarNomeProfissional(nome.trim()), setor: setorFinal, subsetor: subsetor || null, foto, corredor: corredor || null, ladoCorredor: ladoCorredor || null,
          modulo: modulo || null, prateleira: prateleira || null, categoriaGiro: categoriaGiro || null, politicaTroca: politicaTroca || null, precoUnitario: Number(precoUnitario) || 0, porPeso, tamanho: tamanho || null, unidadeMedida, cadastrarEstoque, corredorDeposito: cadastrarEstoque ? (corredorDeposito || null) : null, moduloDeposito: cadastrarEstoque ? (moduloDeposito || null) : null, nivelDeposito: cadastrarEstoque ? (nivelDeposito || null) : null, vaoDeposito: cadastrarEstoque ? (vaoDeposito || null) : null
        })}
          style={{ color: BLUE }} className="w-full mt-2.5 text-xs font-semibold py-2 flex items-center justify-center gap-1.5">
          <CalendarDaysIcon className="w-3.5 h-3.5" /> Alterar a data de validade também
        </button>
      )}
    </div>
  );
}

// ============ Validade ============
function ExpiryView({ T, product, barcode, editing, items, vozPre, onCancel, onVoltar, onSave, onBaixaDireta }) {
  const [validade, setValidade] = useState(editing ? editing.validade : (vozPre?.validade || ""));
  const [diasSelecionados, setDiasSelecionados] = useState(editing ? [editing.diasAlerta, ...(editing.diasAlertaExtras || [])] : [15]);
  const isAcougue = product.setor === "Açougue";
  const [porPeso, setPorPeso] = useState(editing ? !!editing.porPeso : (vozPre?.porPeso ? true : product.porPeso != null ? !!product.porPeso : isAcougue));
  const [quantidade, setQuantidade] = useState(editing ? editing.quantidade || 1 : (
    vozPre?.quantidade != null ? vozPre.quantidade : product.pesoLido || (product.precoLidoEmbutido && product.precoUnitario ? Number((product.precoLidoEmbutido / product.precoUnitario).toFixed(3)) : 1)
  ));
  const [precoUnitario, setPrecoUnitario] = useState(editing ? editing.precoUnitario || "" : product.precoUnitario || "");
  const [tamanho, setTamanho] = useState(editing ? editing.tamanho || "" : (product.tamanho || ""));
  const [unidadeMedida, setUnidadeMedida] = useState(editing
    ? (editing.unidadeMedida === "UN" ? "KG" : editing.unidadeMedida) || "KG"
    : (product.unidadeMedida || unidadeSugeridaPeloSetor(product.setor)));
  const [observacoes, setObservacoes] = useState(editing ? editing.observacoes || "" : "");
  const [confirmarDuplicado, setConfirmarDuplicado] = useState(false);
  const [local, setLocal] = useState(editing ? editing.local || "loja" : "loja");
  const [corredorDeposito, setCorredorDeposito] = useState(editing ? editing.corredorDeposito || "" : product.corredorDeposito || "");
  const [moduloDeposito, setModuloDeposito] = useState(editing ? editing.moduloDeposito || "" : product.moduloDeposito || "");
  const [nivelDeposito, setNivelDeposito] = useState(editing ? editing.nivelDeposito || "" : product.nivelDeposito || "");
  const [vaoDeposito, setVaoDeposito] = useState(editing ? editing.vaoDeposito || "" : product.vaoDeposito || "");
  const [motivoBaixaDireta, setMotivoBaixaDireta] = useState("Enviado para descarte");

  const perecivel = ehPerecivel(product.setor);
  const { opcoes, restritivo, diasRestantesAtual, motivoPerecivel } = useMemo(() => calcularOpcoesAlerta(validade, perecivel), [validade, perecivel]);

  useEffect(() => {
    if (opcoes.length) setDiasSelecionados((prev) => { const filtrado = prev.filter((d) => opcoes.includes(d)); return filtrado.length ? filtrado : [opcoes[opcoes.length - 1]]; });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [validade]);

  function alternarDia(n) {
    setDiasSelecionados((prev) => {
      if (prev.includes(n)) return prev.length > 1 ? prev.filter((d) => d !== n) : prev;
      if (prev.length >= 3) return prev;
      return [...prev, n].sort((a, b) => b - a);
    });
  }

  const podeSalvar = !!validade && opcoes.length > 0 && !!tamanho.trim();
  const jaVencido = !!validade && diasRestantesAtual !== null && diasRestantesAtual <= 0;
  const podeRegistrarPerda = jaVencido && !!tamanho.trim() && !!motivoBaixaDireta && Number(quantidade) > 0;
  const valorTotal = (Number(quantidade) || 0) * (Number(precoUnitario) || 0);

  // Itens por peso costumam repetir o mesmo código de barras (etiqueta da balança) com pesos diferentes —
  // não é duplicidade real, então não bloqueia/avisa nesse caso.
  const duplicado = !editing && validade && !porPeso
    ? items.some((i) => i.barcode === barcode && i.validade === validade)
    : false;

  function handleRegistrarPerda() {
    onBaixaDireta({
      validade, quantidade: porPeso ? clampNumero(quantidade, 0.001, 9999) : clampNumero(quantidade, 1, 99999),
      precoUnitario: clampNumero(precoUnitario, 0, 999999), porPeso,
      tamanho: sanitizarTexto(tamanho.trim(), 20), unidadeMedida,
      observacoes: sanitizarTexto(observacoes.trim(), 300), motivo: motivoBaixaDireta
    });
  }

  function handleSalvar() {
    if (duplicado && !confirmarDuplicado) { setConfirmarDuplicado(true); return; }
    const ordenados = [...diasSelecionados].sort((a, b) => b - a);
    onSave({
      validade, diasAlerta: ordenados[0], diasAlertaExtras: ordenados.slice(1),
      quantidade: porPeso ? clampNumero(quantidade, 0.001, 9999) : clampNumero(quantidade, 1, 99999),
      precoUnitario: clampNumero(precoUnitario, 0, 999999),
      porPeso,
      tamanho: sanitizarTexto(tamanho.trim(), 20), unidadeMedida,
      observacoes: sanitizarTexto(observacoes.trim(), 300),
      local, corredorDeposito: local === "deposito" ? (corredorDeposito || null) : null,
      moduloDeposito: local === "deposito" ? (moduloDeposito || null) : null,
      nivelDeposito: local === "deposito" ? (nivelDeposito || null) : null,
      vaoDeposito: local === "deposito" ? (vaoDeposito || null) : null
    });
  }

  return (
    <div className="px-4 pt-4">
      <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl p-4 border shadow-lg shadow-black/5 mb-4 flex items-center gap-3">
        <Thumb foto={product.foto} size={44} />
        <div className="min-w-0">
          <p className="font-semibold text-sm truncate">{product.nome}</p>
          <div className="flex items-center gap-3 mt-1 flex-wrap">
            <span style={{ color: T.subtext }} className="inline-flex items-center gap-1 text-[11px]"><MapPin size={11} /> {product.subsetor ? `${product.setor} · ${product.subsetor}` : product.setor}{perecivel ? " · perecível" : ""}</span>
            <span style={{ color: T.subtext }} className="inline-flex items-center gap-1 text-[11px] font-mono"><Barcode size={11} /> {barcode}</span>
          </div>
        </div>
      </div>

      <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl p-4 border shadow-lg shadow-black/5 flex flex-col gap-4">
        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 flex items-center gap-1.5"><Calendar size={13} /> Data de validade</label>
          <input type="date" value={validade} onChange={(e) => setValidade(e.target.value)}
            style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder, boxSizing: "border-box", maxWidth: "100%", WebkitAppearance: "none", appearance: "none" }}
            className="w-full min-w-0 border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2" />
        </div>

        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Tamanho / quantidade da embalagem <span style={{ color: RED }}>*</span></label>
          <div className="flex gap-2">
            <input value={tamanho} inputMode="decimal" maxLength={7}
              onChange={(e) => setTamanho(e.target.value.replace(/[^\d.,]/g, "").slice(0, 7))}
              placeholder="Ex: 500, 1, 900"
              style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="flex-1 min-w-0 border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2" />
            <select value={unidadeMedida} onChange={(e) => setUnidadeMedida(e.target.value)}
              style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }}
              className="w-[84px] shrink-0 border rounded-xl px-2 py-2.5 text-sm font-semibold outline-none focus:ring-2">
              {ordemUnidadesPeloSetor(product.setor).map((u) => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>
        </div>

        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 flex items-center gap-1.5"><Clock size={13} /> Avisar quantos dias antes de vencer? <span style={{ color: T.subtext, fontWeight: 400 }}>(até 3)</span></label>

          {validade && diasRestantesAtual !== null && opcoes.length === 0 ? (
            <div style={{ background: RED_SOFT, color: RED_DARK }} className="rounded-xl overflow-hidden">
              <div className="text-xs font-medium px-3 py-2.5 flex items-start gap-2">
                <AlertTriangle size={14} className="mt-0.5 shrink-0" />
                <span>{diasRestantesAtual <= 0 ? "Esta data já venceu ou vence hoje." : "Data muito próxima."} Não é possível definir uma antecedência de alerta.</span>
              </div>
              {onBaixaDireta && jaVencido && (
                <div className="px-3 pb-3">
                  <p className="text-[10.5px] font-semibold mb-1.5">Quantas {porPeso ? "kg" : "unidade(s)"} estão sendo descartadas?</p>
                  <input type="number" inputMode="decimal" min={porPeso ? 0.001 : 1} step={porPeso ? "0.001" : "1"} autoFocus
                    value={quantidade} onChange={(e) => setQuantidade(porPeso ? e.target.value.replace(/[^\d.,]/g, "").replace(",", ".") : e.target.value.replace(/[^\d]/g, ""))}
                    onBlur={(e) => setQuantidade(porPeso ? clampNumero(e.target.value, 0.001, 9999) : clampNumero(e.target.value, 1, 99999))}
                    placeholder={porPeso ? "Ex: 1,235" : "Ex: 3"}
                    style={{ background: "rgba(255,255,255,0.7)", borderColor: "transparent" }}
                    className="w-full border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2 mb-2.5" />
                  <p className="text-[10.5px] font-semibold mb-1.5">Motivo do descarte:</p>
                  <div className="grid grid-cols-2 gap-1.5 mb-2.5">
                    {MOTIVOS_BAIXA.filter((m) => m !== "Promoção aplicada").map((m) => (
                      <button key={m} onClick={() => setMotivoBaixaDireta(m)}
                        style={motivoBaixaDireta === m ? { background: RED_DARK, color: "#fff" } : { background: "rgba(255,255,255,0.6)", color: RED_DARK }}
                        className="text-[10.5px] font-medium py-2 rounded-lg">
                        {m}
                      </button>
                    ))}
                  </div>
                  <button disabled={!podeRegistrarPerda} onClick={handleRegistrarPerda}
                    style={{ background: podeRegistrarPerda ? RED_DARK : "rgba(0,0,0,0.15)" }}
                    className="w-full text-white text-xs font-bold py-2.5 rounded-xl flex items-center justify-center gap-1.5 disabled:opacity-50">
                    <PackageX size={14} /> Registrar perda agora
                  </button>
                  {!tamanho.trim() && <p className="text-[10px] mt-1.5 opacity-80">Preencha o tamanho/embalagem acima pra liberar.</p>}
                </div>
              )}
            </div>
          ) : (
            <>
              <div className="grid grid-cols-6 gap-1.5">
                {DIAS_ALERTA_BASE.map((n) => {
                  const habilitado = opcoes.includes(n);
                  const selecionado = diasSelecionados.includes(n);
                  return (
                    <button key={n} disabled={!habilitado} onClick={() => alternarDia(n)}
                      style={
                        !habilitado ? { background: T.chipBg, color: T.subtext, opacity: 0.4, borderColor: T.border } :
                        selecionado ? { background: RED, color: "#fff", borderColor: RED } :
                        { background: T.inputBg, color: T.text, borderColor: T.border }
                      }
                      className="text-sm font-semibold py-2.5 rounded-xl border relative">
                      {n}
                    </button>
                  );
                })}
              </div>
              {motivoPerecivel && (
                <div style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-[11px] font-medium px-3 py-2 rounded-xl mt-2 flex items-start gap-1.5">
                  <Sparkles size={13} className="mt-0.5 shrink-0" /> <span>Produto perecível: liberado o lançamento mesmo faltando só 1 dia para o vencimento.</span>
                </div>
              )}
              {restritivo && !motivoPerecivel && opcoes.length > 0 && (
                <div style={{ background: RED_SOFT, color: RED_DARK }} className="text-[11px] font-medium px-3 py-2 rounded-xl mt-2 flex items-start gap-1.5">
                  <ShieldAlert size={13} className="mt-0.5 shrink-0" />
                  <span>Faltam apenas {diasRestantesAtual} dia(s) para o vencimento — por segurança, só é possível escolher {opcoes[0]} dia(s) de antecedência.</span>
                </div>
              )}
              {!restritivo && <p style={{ color: T.subtext }} className="text-[11px] mt-1.5">Selecione de 1 a 3 marcos de alerta (ex: 10, 5 e 2 dias antes).</p>}
            </>
          )}
        </div>

        {perecivel && (
          <div>
            <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Como esse item é vendido?</label>
            <div className="flex rounded-xl overflow-hidden" style={{ border: `1px solid ${T.inputBorder}` }}>
              <button type="button" onClick={() => setPorPeso(true)}
                style={porPeso ? { background: BLUE, color: "#fff" } : { background: T.inputBg, color: T.subtext }}
                className="flex-1 text-xs font-semibold py-2.5">Peso (KG)</button>
              <button type="button" onClick={() => setPorPeso(false)}
                style={!porPeso ? { background: BLUE, color: "#fff" } : { background: T.inputBg, color: T.subtext }}
                className="flex-1 text-xs font-semibold py-2.5">Por unidade</button>
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-3">
          <div>
            <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">{porPeso ? "Quantidade (KG)" : "Quantidade"}</label>
            <input type="number" inputMode="decimal" min={porPeso ? "0.001" : "1"} step={porPeso ? "0.001" : "1"} max="99999" value={quantidade}
              onChange={(e) => setQuantidade(porPeso ? e.target.value.replace(/[^\d.,]/g, "").replace(",", ".") : e.target.value.replace(/[^\d]/g, ""))}
              onBlur={(e) => setQuantidade(porPeso ? clampNumero(e.target.value, 0.001, 9999) : clampNumero(e.target.value, 1, 99999))}
              placeholder={porPeso ? "Ex: 1,235" : ""}
              style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2" />
            {(product.pesoLido || product.precoLidoEmbutido) && !editing && (
              <p style={{ color: "#1F9D55" }} className="text-[10px] mt-1 font-medium">✓ Peso lido direto da etiqueta da balança</p>
            )}
          </div>
          <div>
            <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">{porPeso ? "Valor por KG (R$)" : "Preço unitário (R$)"}</label>
            <input type="number" inputMode="decimal" min="0" step="0.01" value={precoUnitario}
              onChange={(e) => setPrecoUnitario(e.target.value)}
              onBlur={(e) => setPrecoUnitario(e.target.value === "" ? "" : clampNumero(e.target.value, 0, 999999))}
              placeholder="0,00" style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2" />
          </div>
        </div>
        {valorTotal > 0 && (
          <div style={{ background: T.chipBg }} className="rounded-xl px-3 py-2.5 -mt-1">
            <p style={{ color: T.subtext }} className="text-[11px]">
              {porPeso ? "Total (calculado automaticamente, não editável): " : "Valor total estimado: "}
              <strong style={{ color: T.text }}>{formatarMoeda(valorTotal)}</strong>
              {porPeso ? "" : ` (atualiza o "valor em risco" da Home automaticamente)`}
            </p>
          </div>
        )}

        <div>
          <div className="flex items-center justify-between mb-1.5">
            <label style={{ color: T.subtext }} className="text-xs font-semibold block">Observações (opcional)</label>
            <span style={{ color: T.subtext }} className="text-[10px]">{observacoes.length}/300</span>
          </div>
          <textarea value={observacoes} maxLength={300} onChange={(e) => setObservacoes(e.target.value)} rows={2} placeholder="Ex: lote da promoção, caixa danificada..."
            style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2 resize-none" />
        </div>

        {duplicado && (
          <div style={{ background: RED_SOFT, color: RED_DARK }} className="text-xs font-medium px-3 py-2 rounded-xl flex items-start gap-2">
            <AlertTriangle size={14} className="mt-0.5 shrink-0" />
            <span>Já existe um produto com este código e esta mesma validade cadastrado. Confirme novamente para salvar mesmo assim.</span>
          </div>
        )}
      </div>

      <div className="flex gap-2 mt-5">
        {!editing && onVoltar && (
          <button onClick={onVoltar} style={{ color: T.subtext, borderColor: T.border }} className="flex items-center justify-center gap-1 text-sm font-medium py-3 px-4 rounded-2xl border">
            <ArrowLeft size={15} /> Voltar
          </button>
        )}
        <button onClick={onCancel} style={{ color: T.subtext, borderColor: T.border }} className="flex-1 text-sm font-medium py-3 rounded-2xl border">Cancelar</button>
        <button disabled={!podeSalvar} onClick={handleSalvar}
          style={{ background: podeSalvar ? BLUE : "#C7CEDA" }} className="flex-[2] text-sm font-semibold py-3 rounded-2xl text-white flex items-center justify-center gap-1.5">
          <Check size={16} /> {editing ? "Salvar alterações" : duplicado && confirmarDuplicado ? "Salvar mesmo assim" : "Salvar alerta"}
        </button>
      </div>
    </div>
  );
}

// ============ Histórico ============
function HistoricoView({ T, historico, items, usuario }) {
  const [periodo, setPeriodo] = useState(30);

  const filtrado = useMemo(() => {
    const limite = Date.now() - periodo * 86400000;
    return historico.filter((h) => new Date(h.dataBaixa).getTime() >= limite);
  }, [historico, periodo]);

  const valorPerdido = filtrado.filter((h) => h.vencidoAntes).reduce((acc, h) => acc + (Number(h.quantidade) || 1) * (Number(h.precoUnitario) || 0), 0);
  const valorTotalMovimentado = filtrado.reduce((acc, h) => acc + (Number(h.quantidade) || 1) * (Number(h.precoUnitario) || 0), 0);

  const dadosGrafico = useMemo(() => {
    const mapa = {};
    filtrado.forEach((h) => { mapa[h.setor] = (mapa[h.setor] || 0) + 1; });
    return Object.entries(mapa).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([setor, qtd]) => ({ setor, qtd }));
  }, [filtrado]);

  // Ranking de perdas por setor, em % do valor total perdido no período
  const rankingSetores = useMemo(() => {
    const mapa = {};
    filtrado.forEach((h) => { mapa[h.setor] = (mapa[h.setor] || 0) + (Number(h.quantidade) || 1) * (Number(h.precoUnitario) || 0); });
    const total = Object.values(mapa).reduce((a, b) => a + b, 0) || 1;
    return Object.entries(mapa).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([setor, valor]) => ({ setor, valor, pct: (valor / total) * 100 }));
  }, [filtrado]);

  const rankingResponsaveis = useMemo(() => {
    const mapa = {};
    filtrado.forEach((h) => { const nome = h.registradoPor || "Não identificado"; mapa[nome] = (mapa[nome] || 0) + 1; });
    return Object.entries(mapa).sort((a, b) => b[1] - a[1]).slice(0, 5);
  }, [filtrado]);
  const maxResp = rankingResponsaveis.length ? rankingResponsaveis[0][1] : 1;

  // Reincidência: mesmo código de barras com múltiplas baixas por vencimento nos últimos 60 dias
  const reincidentes = useMemo(() => {
    const janela = Date.now() - 60 * 86400000;
    const mapa = {};
    historico.filter((h) => h.vencidoAntes && new Date(h.dataBaixa).getTime() >= janela).forEach((h) => {
      if (!mapa[h.barcode]) mapa[h.barcode] = { nome: h.nome, setor: h.setor, datas: [] };
      mapa[h.barcode].datas.push(h.dataBaixa);
    });
    return Object.values(mapa).filter((p) => p.datas.length >= 3).sort((a, b) => b.datas.length - a.datas.length).slice(0, 5);
  }, [historico]);

  function exportarCSV() {
    const header = ["Produto", "Setor", "Código", "Validade", "Ação", "Quantidade", "PrecoUnitario", "DataBaixa", "Responsável"];
    const rows = filtrado.map((h) => [h.nome, h.setor, h.barcode, formatarData(h.validade), h.motivo, h.quantidade || 1, (h.precoUnitario || 0).toFixed(2), formatarDataHora(h.dataBaixa), h.registradoPor || ""]);
    downloadCSV(rows, header, "condor-historico-baixas.csv");
  }
  function exportarPlanilha(formato) {
    const linhas = filtrado.map((h) => ({
      Produto: h.nome, Setor: h.setor, Codigo: h.barcode, Validade: formatarData(h.validade),
      Acao: h.motivo, Quantidade: h.quantidade || 1, PrecoUnitario: h.precoUnitario || 0, DataBaixa: formatarDataHora(h.dataBaixa), Responsavel: h.registradoPor || ""
    }));
    downloadPlanilha(linhas, `condor-historico-baixas.${formato}`, "Historico");
  }

  return (
    <>
    <HistoricoDashboard T={T} filtrado={filtrado} periodo={periodo} setPeriodo={setPeriodo} valorPerdido={valorPerdido} valorTotalMovimentado={valorTotalMovimentado} rankingSetores={rankingSetores} rankingResponsaveis={rankingResponsaveis} reincidentes={reincidentes} exportarCSV={exportarCSV} exportarPlanilha={exportarPlanilha} />
    <div className="lg:hidden px-4 pt-4 pb-6">
      <PalcoPagina className="mb-4" titulo="Histórico de baixas" subtitulo={`Últimos ${periodo} dias`}>
        <ValorPalco rotulo="Perda confirmada (vencidos)" valor={formatarMoeda(valorPerdido)} />
        <PilulasPalco itens={[["Baixas", filtrado.length, "#F5A524"], ["Vencidos", filtrado.filter((h) => h.vencidoAntes).length, "#E31E24"], ["Movimentado", abreviarNumero(valorTotalMovimentado), "#34C77B"]]} />
      </PalcoPagina>

      <div className="flex items-center gap-2 mb-3.5">
        <div className="flex-1 min-w-0"><FaixaChips T={T} valor={periodo} onChange={setPeriodo} opcoes={[[7, "7 dias"], [30, "30 dias"], [90, "90 dias"]]} /></div>
        <div className="flex gap-1.5 shrink-0 mb-3.5">
          <motion.button whileTap={{ scale: 0.92 }} onClick={exportarCSV} aria-label="Exportar CSV" style={{ background: T.card, color: T.text }} className="h-9 px-3 rounded-full text-[11.5px] font-bold flex items-center gap-1 shadow-sm"><Download size={13} /> CSV</motion.button>
          <motion.button whileTap={{ scale: 0.92 }} onClick={() => exportarPlanilha("ods")} aria-label="Exportar planilha" style={{ background: T.card, color: T.text }} className="h-9 px-3 rounded-full text-[11.5px] font-bold flex items-center gap-1 shadow-sm"><FileSpreadsheet size={13} /> ODS</motion.button>
        </div>
      </div>

      {rankingSetores.length > 0 && (
        <CartaoNovo T={T} idx={0} titulo="Perdas por setor (% do valor)" Icone={LayoutGrid} cor={RED_DARK}>
          {rankingSetores.map((r, k) => <BarraRank key={r.setor} T={T} pos={k + 1} rotulo={r.setor} pct={r.pct} texto={`${r.pct.toFixed(0)}%`} />)}
        </CartaoNovo>
      )}
      {dadosGrafico.length > 0 && (
        <CartaoNovo T={T} idx={1} titulo="Baixas por setor" Icone={Layers} cor={BLUE}>
          {dadosGrafico.map((d, k) => <BarraRank key={d.setor} T={T} pos={k + 1} rotulo={d.setor} pct={(d.qtd / dadosGrafico[0].qtd) * 100} texto={String(d.qtd)} cor={BLUE} />)}
        </CartaoNovo>
      )}
      {reincidentes.length > 0 && (
        <CartaoNovo T={T} idx={2} titulo="Produtos reincidentes (60 dias)" Icone={Repeat} cor={RED_DARK}>
          <div className="flex flex-col gap-2">
            {reincidentes.map((pr) => (
              <div key={pr.nome + pr.datas.length} style={{ background: RED_SOFT }} className="rounded-2xl px-3.5 py-2.5">
                <p style={{ color: RED_DARK }} className="text-[13px] font-extrabold">{pr.nome}</p>
                <p style={{ color: RED_DARK }} className="text-[11px] mt-0.5 opacity-80">{pr.setor} · {pr.datas.length} vencimentos · média {(pr.datas.length / 2).toFixed(1)}/mês</p>
              </div>
            ))}
          </div>
        </CartaoNovo>
      )}
      {rankingResponsaveis.length > 0 && (
        <CartaoNovo T={T} idx={3} titulo="Baixas por responsável" Icone={Users2} cor={BLUE}>
          {rankingResponsaveis.map(([nome, qtd], k) => <BarraRank key={nome} T={T} pos={k + 1} rotulo={nome} pct={(qtd / maxResp) * 100} texto={String(qtd)} cor={BLUE} />)}
        </CartaoNovo>
      )}

      <div style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="rounded-[22px] px-4 py-3.5 mb-4 flex items-start gap-2.5">
        <Info size={15} className="mt-0.5 shrink-0" />
        <p className="text-[11.5px] leading-relaxed">Referência do setor: o vencimento responde por cerca de 38% das perdas em supermercados brasileiros, geralmente entre 1% e 1,5% do faturamento. O relatório completo em PDF para a gerência é gerado na aba <b>Torre</b>.</p>
      </div>

      <p style={{ color: T.subtext }} className="text-[11px] font-bold uppercase tracking-[.1em] mb-2.5">Baixas registradas · {filtrado.length}</p>
      {filtrado.length === 0 ? (
        <EstadoVazioNovo T={T} Icone={History} titulo="Nenhuma baixa neste período" texto="Baixas registradas na tela inicial aparecem aqui." />
      ) : (
        <div className="flex flex-col gap-2.5">
          {filtrado.map((h, k) => (
            <motion.div key={h.id + h.dataBaixa} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ type: "spring", stiffness: 320, damping: 26, delay: Math.min(k * 0.03, 0.3) }}
              style={{ background: T.card }} className="rounded-[22px] shadow-md shadow-black/5 p-3 flex items-center gap-3">
              <Thumb foto={h.foto} size={50} rounded="rounded-[16px]" />
              <div className="flex-1 min-w-0">
                <p style={{ color: T.text }} className="font-bold text-[13.5px] leading-tight truncate">{h.nome}</p>
                <p style={{ color: T.subtext }} className="text-[11.5px] mt-0.5 truncate">{h.setor} · {formatarDataHora(h.dataBaixa)}</p>
                {h.registradoPor && <p style={{ color: T.subtext }} className="text-[11px] truncate">Por {h.registradoPor}</p>}
              </div>
              <div className="flex flex-col items-end gap-1 shrink-0">
                <span style={h.vencidoAntes ? { background: RED_SOFT, color: RED_DARK } : { background: BLUE_SOFT, color: BLUE_DARK }} className="text-[10.5px] font-bold px-2.5 py-1 rounded-full text-right">{h.motivo}</span>
                <span style={{ color: T.subtext }} className="text-[11px] font-semibold tabular-nums">{h.quantidade || 1} un</span>
              </div>
            </motion.div>
          ))}
        </div>
      )}
    </div>
  </>
  );
}

// ============ Auditoria (página própria, acessada pelos Ajustes) ============
function AuditoriaView({ T, auditoria }) {
  const [busca, setBusca] = useState("");

  const filtrada = useMemo(() => {
    const termo = busca.trim().toLowerCase();
    if (!termo) return auditoria;
    return auditoria.filter((a) =>
      (a.usuario || "").toLowerCase().includes(termo) ||
      (a.acao || "").toLowerCase().includes(termo) ||
      (a.detalhe || "").toLowerCase().includes(termo)
    );
  }, [auditoria, busca]);

  const grupos = useMemo(() => {
    const mapa = {};
    filtrada.forEach((a) => {
      const chave = formatarDataExtenso(a.criadoEm);
      if (!mapa[chave]) mapa[chave] = [];
      mapa[chave].push(a);
    });
    return Object.entries(mapa);
  }, [filtrada]);

  return (
    <>
    <AuditoriaDashboard T={T} auditoria={auditoria} filtrada={filtrada} busca={busca} setBusca={setBusca} />
    <div className="px-4 pt-4 pb-6 lg:hidden">
      <PalcoPagina className="mb-4" titulo="Auditoria" subtitulo="Tudo o que foi feito no app, em ordem">
        <PilulasPalco itens={[["Registros", auditoria.length, "#F5A524"], ["Hoje", auditoria.filter((a) => isSameDay(a.criadoEm, new Date().toISOString())).length, "#34C77B"], ["Pessoas", new Set(auditoria.map((a) => a.usuario || "—")).size, "#6CB4FF"]]} />
      </PalcoPagina>

      <div className="relative mb-4">
        <MagnifyingGlassIcon className="w-4 h-4 absolute left-4 top-1/2 -translate-y-1/2" style={{ color: T.subtext }} />
        <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar por pessoa, ação ou detalhe..."
          style={{ background: T.card, color: T.text, borderColor: T.inputBorder }} className="w-full rounded-full pl-11 pr-10 py-3 text-sm border outline-none focus:ring-2 shadow-sm" />
        {busca && <button onClick={() => setBusca("")} aria-label="Limpar busca" style={{ background: T.chipBg }} className="absolute right-2.5 top-1/2 -translate-y-1/2 h-6 w-6 rounded-full flex items-center justify-center"><XMarkIcon className="w-3 h-3" style={{ color: T.subtext }} /></button>}
      </div>

      {grupos.length === 0 ? (
        <EstadoVazioNovo T={T} Icone={ListChecks} titulo="Nenhum registro encontrado" texto={busca ? "Ajuste a busca." : "As ações do app aparecem aqui conforme acontecem."} />
      ) : (
        <div className="flex flex-col gap-5">
          {grupos.map(([data, itens]) => (
            <div key={data}>
              <p style={{ color: T.subtext }} className="text-[11px] font-bold uppercase tracking-[.1em] mb-2.5 flex items-center gap-1.5">
                <CalendarDaysIcon className="w-3.5 h-3.5" /> {data} <span style={{ background: T.chipBg }} className="rounded-full px-1.5 text-[10px] tabular-nums">{itens.length}</span>
              </p>
              <div className="relative pl-1">
                <div aria-hidden style={{ background: T.chipBg }} className="absolute left-[19px] top-3 bottom-3 w-[2px] rounded-full" />
                <div className="flex flex-col gap-2.5">
                  {itens.map((a, k) => (
                    <motion.div key={a.id || k} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: Math.min(k * 0.03, 0.25) }} className="relative flex items-start gap-3">
                      <span style={{ background: T.card, border: `2px solid ${BLUE}` }} className="relative z-10 h-[18px] w-[18px] rounded-full shrink-0 mt-3.5 ml-[2px]" />
                      <div style={{ background: T.card }} className="flex-1 min-w-0 rounded-[20px] shadow-md shadow-black/5 px-3.5 py-3">
                        <p style={{ color: T.text }} className="text-[13px] leading-snug"><strong>{a.usuario || "Alguém"}</strong> {a.acao}</p>
                        {a.detalhe && <p style={{ color: T.subtext }} className="text-[11.5px] mt-1 leading-snug">{a.detalhe}</p>}
                        <p style={{ color: T.subtext }} className="text-[10.5px] mt-1.5 font-mono">{formatarDataHoraExtenso(a.criadoEm)}</p>
                      </div>
                    </motion.div>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  </>
  );
}

// Sheet: escolher quais seções entram no PDF gerencial antes de gerar
function SelecionarSecoesRelatorioSheet({ T, secoesDisponiveis, selecionadas, onAlternar, onFechar, onGerar }) {
  const todasMarcadas = secoesDisponiveis.every((s) => selecionadas.has(s.id));
  return (
    <div className="fixed inset-0 z-[60] flex items-end justify-center sm:items-center">
      <div onClick={onFechar} className="absolute inset-0 bg-black/60" />
      <div style={{ background: T.card }} className="relative w-full max-w-md lg:max-w-lg lg:ring-1 lg:ring-black/10 lg:shadow-2xl rounded-t-[28px] p-5 pb-[calc(1.75rem+env(safe-area-inset-bottom))] max-h-[88dvh] overflow-y-auto sm:rounded-2xl">
        <h3 className="font-bold text-sm mb-1">O que entra no relatório?</h3>
        <p style={{ color: T.subtext }} className="text-[11px] mb-3">O resumo geral (KPIs e perdas do mês) sempre entra. Escolha as seções extras:</p>

        <button onClick={() => secoesDisponiveis.forEach((s) => { if (todasMarcadas ? selecionadas.has(s.id) : !selecionadas.has(s.id)) onAlternar(s.id); })}
          style={{ color: BLUE }} className="text-[11px] font-semibold mb-2">
          {todasMarcadas ? "Desmarcar todas" : "Marcar todas"}
        </button>

        <div className="flex flex-col gap-1.5 mb-4">
          {secoesDisponiveis.map((s) => {
            const marcado = selecionadas.has(s.id);
            return (
              <button key={s.id} onClick={() => onAlternar(s.id)} style={{ background: T.chipBg }}
                className="w-full flex items-center justify-between gap-2 rounded-xl px-3 py-2.5">
                <span className="text-xs font-medium">{s.label}</span>
                <div style={marcado ? { background: BLUE, borderColor: BLUE } : { borderColor: T.inputBorder }}
                  className="h-5 w-5 rounded-md border flex items-center justify-center shrink-0">
                  {marcado && <Check size={13} color="#fff" />}
                </div>
              </button>
            );
          })}
        </div>

        <div className="flex gap-2">
          <button onClick={onFechar} style={{ color: T.subtext }} className="flex-1 text-xs py-2.5">Cancelar</button>
          <button onClick={onGerar} disabled={selecionadas.size === 0} style={{ background: RED_DARK, color: "#fff" }}
            className="flex-[2] text-sm font-semibold py-2.5 rounded-xl flex items-center justify-center gap-1.5 disabled:opacity-40">
            <Download size={15} /> Gerar PDF
          </button>
        </div>
      </div>
    </div>
  );
}

// ============ Relatórios (resumo geral, setores, itens, financeiro, atividade — com exportação em PDF/ODS/XLSX/CSV) ============
// ============ Relatórios — versão dashboard (PC) ============
