            <DashHBars T={T} data={rondasResumo.porSetor.slice(0, 8).map(([s, d]) => ({ label: s, value: d.concluidas + d.parciais, color: "#1F9D55", right: `${d.concluidas} ok · ${d.parciais} parc.` }))} />
